ss_vars.day_cell_height", "descriptionFallback": "Month-view day cell height."}, {"name": "--origam-calendar__day-cell---bg-color-today", "defaultValue": "{color.action.primary.bgSubtle}", "descriptionKey": "components.calendar.css_vars.today_bg", "descriptionFallback": "Background of today''s cell."}, {"name": "--origam-calendar__day-cell---bg-color-weekend", "defaultValue": "{color.surface.sunken}", "descriptionKey": "components.calendar.css_vars.weekend_bg", "descriptionFallback": "Background of weekend cells when weekendHighlight=true."}, {"name": "--origam-calendar__event---bg-color-default", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.calendar.css_vars.event_bg", "descriptionFallback": "Default event chip background."}, {"name": "--origam-calendar__toolbar---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.calendar.css_vars.toolbar_bg", "descriptionFallback": "Toolbar background."}, {"name": "--origam-calendar__timeline---slot-height", "defaultValue": "32px", "descriptionKey": "components.calendar.css_vars.slot_height", "descriptionFallback": "Height per timeline slot row (proportional to slotDuration)."}], "exposed": [{"name": "visibleDateRange", "type": "ComputedRef<{ start: Date; end: Date }>", "descriptionKey": "components.calendar.exposed.visible_date_range", "descriptionFallback": "Start and end Date of the currently rendered period (useful for fetching remote events)."}, {"name": "expandedEvents", "type": "ComputedRef<IEvent[]>", "descriptionKey": "components.calendar.exposed.expanded_events", "descriptionFallback": "Events after recurring expansion within the visible date range."}, {"name": "navigate", "type": "(direction: TCalendarNavigate) => void", "descriptionKey": "components.calendar.exposed.navigate", "descriptionFallback": "Programmatically navigate: \"prev\", \"next\" or \"today\"."}, {"name": "setView", "type": "(view: TCalendarView) => void", "descriptionKey": "compone