INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a2edd702-ce20-4f98-971c-b6469c8b8cf0', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'card', 'Card', 'Surface', NULL, 'mdi-card-outline', 'components.catalog.card.description', 'Versatile surface container with title, subtitle, image asset, text body, footer slots, link support, loading states and ripple interaction.', NULL, NULL, 'origam-card', NULL, 'packages/ds/src/components/Card/OrigamCard.vue', 'origam', NULL, NULL, '/stories/?story=components-card--design', '/docs/components/Card/OrigamCard.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.card.a11y.disabled_tabindex", "noteFallback": "When disabled=true, tabindex=\"-1\" is set to remove the card from the tab order."}, {"noteKey": "components.card.a11y.link_semantics", "noteFallback": "When href or to is set, the card root renders as <a> with proper link semantics. The ripple v-ripple directive triggers on the native click event."}, {"noteKey": "components.card.a11y.focus_visible", "noteFallback": "Focus-visible outline is applied via :focus-visible in the component SCSS — visible for keyboard navigation, not mouse clicks."}, {"noteKey": "components.card.a11y.overlay_hidden", "noteFallback": "The __overlay and __underlay spans are aria-hidden (inert layers)."}, {"noteKey": "components.card.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to ensure accessible foreground/background contrast when color is set."}, {"noteKey": "components.card.a11y.loader", "noteFallback": "The OrigamProgress inside the loader slot has role=\"progressbar\". OrigamSkeleton is aria-hidden (decorative)."}], "roles": ["article", "link", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.card.a11y.key_tab", "actionFallback": "Moves focus to the card when it is interactive (link=true or href/to is set)."}, {"key": "Enter / Space", "actionKey": "components.card.a11y.key_activate", "actionFallback": "Activates the card link or click handler when focused."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-card---background", "descriptionKey": "components.card.tokens.background", "descriptionFallback": "Card background."}, {"type": "shadow", "value": "var(--origam-shadow---sm)", "tokenPath": "--origam-card---box-shadow", "descriptionKey": "components.card.tokens.box_shadow", "descriptionFallback": "Default elevation shadow."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-card---box-shadow-hover", "descriptionKey": "components.card.tokens.box_shadow_hover", "descriptionFallback": "Hover elevation shadow for interactive cards."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-card---transition-duration", "descriptionKey": "components.card.tokens.transition_duration", "descriptionFallback": "Transition duration for shadow and opacity."}, {"type": "number", "value": "var(--origam-opacity---0)", "tokenPath": "--origam-card__overlay---opacity", "descriptionKey": "components.card.tokens.overlay_opacity", "descriptionFallback": "Resting overlay opacity (0 = invisible)."}, {"type": "number", "value": "var(--origam-opacity---12)", "tokenPath": "--origam-card---overlay-opacity-hover", "descriptionKey": "components.card.tokens.overlay_opacity_hover", "descriptionFallback": "Overlay opacity on hover (12%)."}, {"type": "number", "value": "var(--origam-opacity---60)", "tokenPath": "--origam-card---opacity-disabled", "descriptionKey": "components.card.tokens.opacity_disabled", "descriptionFallback": "Card