r block. Contains title and subtitle divs."}, {"cls": ".origam-chart-cartesian__body", "num": 2, "descriptionKey": "components.chart_cartesian.anatomy.body", "descriptionFallback": "Body container. Wraps the SVG, drilldown breadcrumb and zoom controls."}, {"cls": ".origam-chart-cartesian__axis", "num": 3, "descriptionKey": "components.chart_cartesian.anatomy.axis", "descriptionFallback": "<g> element holding all axis tick labels and grid lines."}, {"cls": ".origam-chart__series", "num": 4, "descriptionKey": "components.chart_cartesian.anatomy.series", "descriptionFallback": "<g> container for series path, area fill, or bar/column rects."}, {"cls": ".origam-chart__legend (via OrigamChartLegend)", "num": 5, "descriptionKey": "components.chart_cartesian.anatomy.legend", "descriptionFallback": "Legend list rendered by OrigamChartLegend. grid-area: legend."}], "svgDesc": "Schematic of the cartesian chart component with numbered internal parts.", "svgTitle": "Anatomy of OrigamChartCartesian", "rootClass": "origam-chart-cartesian", "figcaption": "Anatomy of <code>&lt;origam-chart-cartesian&gt;</code> — 5 internal parts.", "svgViewBox": "0 0 640 240"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart_cartesian.css_vars.background_color", "descriptionFallback": "Chart root background colour."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart_cartesian.css_vars.padding", "descriptionFallback": "Inner padding of the chart root."}, {"name": "--origam-chart---gap", "defaultValue": "{space.3}", "descriptionKey": "components.chart_cartesian.css_vars.gap", "descriptionFallback": "Gap between header, body and legend areas."}, {"name": "--origam-chart__grid---stroke-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.chart_cartesian.css_vars.grid_stroke_color", "descriptionFallback": "Grid line stroke colour."}, {"name": "--origam-chart__tooltip---background-color", "defaultValue": "{color.surface.inverse}", "descriptionKey": "components.chart_cartesian.css_vars.tooltip_bg", "descriptionFallback": "Tooltip background colour."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "line", "value": "line"}, {"label": "area", "value": "area"}, {"label": "bar", "value": "bar"}, {"label": "column", "value": "column"}, {"label": "scatter", "value": "scatter"}, {"label": "spline", "value": "spline"}, {"label": "stepped-line", "value": "stepped-line"}], "labelKey": "components.chart_cartesian.playground.type", "defaultValue": "line", "labelFallback": "Chart type"}, {"kind": "switch", "prop": "stacked", "labelKey": "components.chart_cartesian.playground.stacked", "defaultValue": false, "labelFallback": "Stacked"}, {"kind": "switch", "prop": "showGrid", "labelKey": "components.chart_cartesian.playground.show_grid", "defaultValue": true, "labelFallback": "Show grid"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_cartesian.playground.show_legend", "defaultValue": true, "labelFallback": "Show legend"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_cartesian.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "switch", "prop": "zoomable", "labelKey": "components.chart_cartesian.playground.zoomable", "defaultValue": false, "labelFallback": "Zoomable"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
