xt x=\"240\" y=\"175\" font-size=\"18\" fill=\"var(--origam-color__text---primary,#1e1b4b)\" text-anchor=\"middle\" font-weight=\"700\" font-family=\"sans-serif\">72%</text>\n  <circle cx=\"200\" cy=\"165\" r=\"8\" fill=\"var(--origam-color__action--primary---bg,#7c3aed)\"/>\n  <text x=\"200\" y=\"169\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"108\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---secondary,#6b7280)\" text-anchor=\"middle\" font-family=\"sans-serif\">0</text>\n  <text x=\"372\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---secondary,#6b7280)\" text-anchor=\"middle\" font-family=\"sans-serif\">100</text>\n  <circle cx=\"108\" cy=\"188\" r=\"7\" fill=\"var(--origam-color__action--primary---bg,#a855f7)\"/>\n  <text x=\"108\" y=\"192\" font-size=\"7\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "legend": [{"cls": ".origam-chart-gauge__header", "num": 1, "descriptionKey": "components.chart_gauge.anatomy.header", "descriptionFallback": "Header block. Contains title and subtitle divs."}, {"cls": ".origam-chart-gauge__body", "num": 2, "descriptionKey": "components.chart_gauge.anatomy.body", "descriptionFallback": "Body container. Wraps the SVG and empty-state overlay."}, {"cls": ".origam-chart__gauge-track", "num": 3, "descriptionKey": "components.chart_gauge.anatomy.track", "descriptionFallback": "Background arc path — always full 270 degrees."}, {"cls": ".origam-chart__gauge-fill", "num": 4, "descriptionKey": "components.chart_gauge.anatomy.fill", "descriptionFallback": "Foreground arc path — length proportional to value ratio."}, {"cls": ".origam-chart__gauge-value", "num": 5, "descriptionKey": "components.chart_gauge.anatomy.value", "descriptionFallback": "Centre value label. Hidden when gaugeShowValue=false."}, {"cls": ".origam-chart__gauge-endpoint (min/max)", "num": 6, "descriptionKey": "components.chart_gauge.anatomy.endpoints", "descriptionFallback": "Min and max labels at arc endpoints. Hidden when gaugeShowEndpoints=false."}], "svgDesc": "Schematic of the gauge chart component with numbered internal parts.", "svgTitle": "Anatomy of OrigamChartGauge", "rootClass": "origam-chart-gauge", "figcaption": "Anatomy of <code>&lt;origam-chart-gauge&gt;</code> — 6 internal parts.", "svgViewBox": "0 0 480 260"}, "cssVars": [{"name": "--origam-chart---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.chart_gauge.css_vars.background_color", "descriptionFallback": "Chart root background colour."}, {"name": "--origam-chart---padding", "defaultValue": "{space.3}", "descriptionKey": "components.chart_gauge.css_vars.padding", "descriptionFallback": "Inner padding of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_gauge.css_vars.animation_duration", "descriptionFallback": "Duration of the fill arc animation."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.chart_gauge.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_gauge.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "gaugeShowEndpoints", "labelKey": "components.chart_gauge.playground.gauge_show_endpoints", "defaultValue": true, "labelFallback": "Gauge Show Endpoints"}, {"kind": "switch", "prop": "gaugeShowValue", "labelKey": "components.chart_gauge.playground.gauge_show_value", "defaultValue": true, "labelFallback": "Gauge Show Value"}, {"kind": "switch", "prop": "animated", "labelKey": "components.chart_gauge.playground.animated", "defaultValue": true, "labelFallback": "Animated"}, {"kind": "select", "prop": "colorScheme", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_gauge.playground.color_scheme", "defaultValue": "", "labelFallback": "Color Scheme"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('12008a64-b3bf-4620-b1cd-9b0b2009ada2', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'chart-heatmap', 'ChartHeatmap', 'Data Display', NULL, 'mdi-grid', 'components.catalog.chart_heatmap.description', 'Rectangular heatmap chart. Renders a grid of SVG <rect> cells coloured by value via CSS color-mix interpolation. Common uses: GitHub activity grids, correlation matrices, weekday × hour patterns.', NULL, NULL, 'origam-chart-heatmap', NULL, 'packages/ds/src/components/Chart/OrigamChartHeatmap.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-heatmap--design', '/docs/components/Chart/OrigamChartHeatmap.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_heatmap.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"heatmap chart\")."}, {"noteKey": "components.chart_heatmap.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing column and row counts."}, {"noteKey": "components.chart_heatmap.a11y.cell_aria", "noteFallback": "Each cell has aria-label in the format \"xCat × yCat: value\" for screen reader announcement."}, {"noteKey": "components.chart_heatmap.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_heatmap.a11y.key_tab", "actionFallback": "Moves focus through each cell (tabindex=\"0\")."}, {"key": "Enter / Space", "actionKey": "components.chart_heatmap.a11y.key_activate", "actionFallback": "Activates the focused cell, firing the point-click emit."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"28\" width=\"636\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header (title + subtitle)</text>\n  <rect x=\"70\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 10%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"156\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 35%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"242\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 60%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"328\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 80%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"414\" y=\"52\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 95%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"70\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 20%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"156\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 55%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"242\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 40%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"328\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 75%, rgba(8,145,178,0.8))\"/>\n  <rect x=\"414\" y=\"92\" width=\"82\" height=\"36\" rx=\"2\" fill=\"color-mix(in srgb, rgba(239,68,68,0.8) 30%, rgba(8,145,178,0.8))\"/>\n  <text x=\"50\" y=\"74\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">Mon</text>\n  <text x=\"50\" y=\"114\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">Tue</text>\n  <text x=\"111\" y=\"142\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">9h</text>\n  <text x=\"197\" y=\"142\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">12h</text>\n  <rect x=\"70\" y=\"150\" width=\"426\" height=\"10\" rx=\"2\" fill=\"url(#origam-hm-grad)\"/>\n  <defs><linearGradient id=\"origam-hm-grad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0%\" stop-color=\"rgba(8,145,178,0.8)\"/><stop offset=\"100%\" stop-color=\"rgba(239,68,68,0.8)\"/></linearGradient></defs>\n  <text x=\"70\" y=\"173\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\">0</text>\n  <text x=\"496\" y=\"173\" font-size=\"7\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\">50</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"78\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"78\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"50\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"50\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"111\" cy=\"142\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"111\" y=\"146\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"78\" cy=\"155\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"78\" y=\"159\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"36\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"225\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② cell fill = CSS color-mix(in srgb, colorRange[1] N%, colorRange[0]) — ⑤ gradient legend</text>\n", "code": "<div class=\"origam-chart-heatmap\" role=\"figure\" aria-label=\"Weekly activity\">\n  <header class=\"origam-chart-heatmap__header\">\n    <div class=\"origam-chart-heatmap__title\">Weekly activity</div>\n  </header>\n\n  <div class=\"origam-chart-heatmap__body\">\n    <svg class=\"origam-chart-heatmap__svg origam-chart__svg\" role=\"img\">\n      <title>Weekly activity</title>\n      <desc>Heatmap chart with 5 columns and 4 rows.</desc>\n\n      <defs>\n        <linearGradient id=\"origam-heatmap-legend-gradient\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\">\n          <stop offset=\"0%\" />\n          <stop offset=\"100%\" />\n        </linearGradient>\n      </defs>\n\n      <!-- cell grid -->\n      <g class=\"origam-chart__heatmap-series\">\n        <g class=\"origam-chart__heatmap-cell-group\">\n          <rect class=\"origam-chart__heatmap-cell\" tabindex=\"0\" role=\"button\" />\n          <text class=\"origam-chart__heatmap-label\">42</text>\n        </g>\n      </g>\n\n      <!-- axis labels -->\n      <g class=\"origam-chart__heatmap-x-axis\">\n        <text class=\"origam-chart__heatmap-axis-label origam-chart__heatmap-axis-label--x\">Mon</text>\n      </g>\n      <g class=\"origam-chart__heatmap-y-axis\">\n        <text class=\"origam-chart__heatmap-axis-label origam-chart__heatmap-axis-label--y\">9h</text>\n      </g>\n\n      <!-- gradient legend (showGradientLegend=true) -->\n      <g class=\"origam-chart__heatmap-gradient-legend\">\n        <rect fill=\"url(#origam-heatmap-legend-gradient)\" />\n        <text class=\"origam-chart__heatmap-legend-label\">0</text>\n        <text class=\"origam-chart__heatmap-legend-label\">50</text>\n      </g>\n    </svg>\n\n    <!-- tooltip -->\n    <origam-chart-tooltip />\n  </div>\n</div>", "legend": [{"cls": ".origam-chart-heatmap", "num": 1, "descriptionKey": "components.chart_heatmap.anatomy.root", "descriptionFallback": "Root element. CSS grid with areas: header / body. role=\"figure\" + aria-label from title."}, {"cls": ".origam-chart__heatmap-cell", "num": 2, "descriptionKey": "components.chart_heatmap.anatomy.cell", "descriptionFallback": "SVG <rect> for each data cell. Fill is CSS color-mix interpolated between colorRange endpoints. tabindex=\"0\" + role=\"button\"."}, {"cls": ".origam-chart__heatmap-axis-label--y", "num": 3, "descriptionKey": "components.chart_heatmap.anatomy.y_label", "descriptionFallback": "Y-axis row labels (left side). Hidden when showAxis=false."}, {"cls": ".origam-chart__heatmap-axis-label--x", "num": 4, "descriptionKey": "components.chart_heatmap.anatomy.x_label", "descriptionFallback": "X-axis column labels (bottom). Hidden when showAxis=false."}, {"cls": ".origam-chart__heatmap-gradient-legend", "num": 5, "descriptionKey": "components.chart_heatmap.anatomy.gradient_legend", "descriptionFallback": "Inline SVG gradient bar with min/max value labels. Visible when showGradientLegend=true and legendPosition is top or bottom."}, {"cls": ".origam-chart-heatmap__header", "num": 6, "descriptionKey": "components.chart_heatmap.anatomy.header", "descriptionFallback": "Title and subtitle block. Rendered only when title or subtitle is provided."}], "classes": [{"cls": "origam-chart-heatmap", "descriptionKey": "components.chart_heatmap.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-chart-heatmap__header", "descriptionKey": "components.chart_heatmap.anatomy.header", "descriptionFallback": "Title/subtitle block."}, {"cls": "origam-chart-heatmap__title", "descriptionKey": "components.chart_heatmap.anatomy.title", "descriptionFallback": "Primary title."}, {"cls": "origam-chart-heatmap__subtitle", "descriptionKey": "components.chart_heatmap.anatomy.subtitle", "descriptionFallback": "Subtitle."}, {"cls": "origam-chart-heatmap__body", "descriptionKey": "components.chart_heatmap.anatomy.body", "descriptionFallback": "Body containing the SVG."}, {"cls": "origam-chart-heatmap__svg", "descriptionKey": "components.chart_heatmap.anatomy.svg", "descriptionFallback": "SVG canvas."}, {"cls": "origam-chart__heatmap-cell-group", "descriptionKey": "components.chart_heatmap.anatomy.cell_group", "descriptionFallback": "<g> grouping one cell and its label."}, {"cls": "origam-chart__heatmap-cell", "descriptionKey": "components.chart_heatmap.anatomy.cell", "descriptionFallback": "Cell <rect>. Fill = color-mix interpolation."}, {"cls": "origam-chart__heatmap-cell--active", "descriptionKey": "components.chart_heatmap.anatomy.cell_active", "descriptionFallback": "Active modifier on hover/focus."}, {"cls": "origam-chart__heatmap-label", "descriptionKey": "components.chart_heatmap.anatomy.cell_label", "descriptionFallback": "Numeric value label centred in the cell."}, {"cls": "origam-chart__heatmap-axis-label", "descriptionKey": "components.chart_heatmap.anatomy.axis_label", "descriptionFallback": "Axis label (shared base class)."}, {"cls": "origam-chart__heatmap-axis-label--x", "descriptionKey": "components.chart_heatmap.anatomy.x_label", "descriptionFallback": "X-axis column label."}, {"cls": "origam-chart__heatmap-axis-label--y", "descriptionKey": "components.chart_heatmap.anatomy.y_label", "descriptionFallback": "Y-axis row label."}, {"cls": "origam-chart__heatmap-gradient-legend", "descriptionKey": "components.chart_heatmap.anatomy.gradient_legend", "descriptionFallback": "Inline gradient legend group."}, {"cls": "origam-chart__heatmap-legend-label", "descriptionKey": "components.chart_heatmap.anatomy.legend_label", "descriptionFallback": "Min/max value label beside the gradient bar."}, {"cls": "origam-chart-heatmap--no-animation", "descriptionKey": "components.chart_heatmap.anatomy.mod_no_animation", "descriptionFallback": "Disables entry animation."}], "svgDesc": "Schematic of the ChartHeatmap component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartHeatmap", "rootClass": "origam-chart-heatmap", "figcaption": "Anatomy of <code>&lt;origam-chart-heatmap&gt;</code> — 6 internal parts. Cell colour interpolated via CSS <code>color-mix(in srgb, …)</code>.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-chart---gap", "defaultValue": "12px", "descriptionKey": "components.chart_heatmap.css_vars.gap", "descriptionFallback": "Gap between header and body areas."}, {"name": "--origam-chart---padding", "defaultValue": "12px", "descriptionKey": "components.chart_heatmap.css_vars.padding", "descriptionFallback": "Internal padding of the chart root."}, {"name": "--origam-chart---background-color", "defaultValue": "transparent", "descriptionKey": "components.chart_heatmap.css_vars.background_color", "descriptionFallback": "Background colour of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_heatmap.css_vars.animation_duration", "descriptionFallback": "Entry animation duration. Driven by animationDuration prop."}, {"name": "--origam-chart__heatmap---stroke-color", "defaultValue": "var(--origam-color-surface-default, #ffffff)", "descriptionKey": "components.chart_heatmap.css_vars.stroke_color", "descriptionFallback": "Stroke colour of cell rects (creates visible gap between cells)."}, {"name": "--origam-chart__heatmap---stroke-width", "defaultValue": "0.5", "descriptionKey": "components.chart_heatmap.css_vars.stroke_width", "descriptionFallback": "Stroke width of cell rects."}, {"name": "--origam-chart__heatmap-label---font-size", "defaultValue": "0.5625rem", "descriptionKey": "components.chart_heatmap.css_vars.label_font_size", "descriptionFallback": "Font size of cell value labels."}, {"name": "--origam-chart__heatmap-label---color", "defaultValue": "#ffffff", "descriptionKey": "components.chart_heatmap.css_vars.label_color", "descriptionFallback": "Fill colour of cell value labels."}, {"name": "--origam-chart__heatmap-axis-label---font-size", "defaultValue": "0.625rem", "descriptionKey": "components.chart_heatmap.css_vars.axis_label_font_size", "descriptionFallback": "Font size of axis labels."}, {"name": "--origam-chart__title---font-size", "defaultValue": "1.125rem", "descriptionKey": "components.chart_heatmap.css_vars.title_font_size", "descriptionFallback": "Font size of the chart title."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_heatmap.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_heatmap.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_heatmap.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "showLabel", "labelKey": "components.chart_heatmap.playground.show_label", "defaultValue": true, "labelFallback": "Show Label"}, {"kind": "switch", "prop": "showAxis", "labelKey": "components.chart_heatmap.playground.show_axis", "defaultValue": true, "labelFallback": "Show Axis"}, {"kind": "switch", "prop": "showGradientLegend", "labelKey": "components.chart_heatmap.playground.show_gradient_legend", "defaultValue": true, "labelFallback": "Show Gradient Legend"}, {"kind": "switch", "prop": "showLegend", "labelKey": "components.chart_heatmap.playground.show_legend", "defaultValue": true, "labelFallback": "Show Legend"}, {"kind": "switch", "prop": "showTooltip", "labelKey": "components.chart_heatmap.playground.show_tooltip", "defaultValue": true, "labelFallback": "Show Tooltip"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1acd1d2f-24bb-4db6-8da1-bfb8d97b5cfe', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'chart-honeycomb', 'ChartHoneycomb', 'Data Display', NULL, 'mdi-hexagon-multiple-outline', 'components.catalog.chart_honeycomb.description', 'Hexagonal tile-map chart. Renders a grid of SVG <polygon> hexagons positioned by (x=col, y=row) indices. Supports pointy-top and flat-top orientations, categorical and heatmap colour modes.', NULL, NULL, 'origam-chart-honeycomb', NULL, 'packages/ds/src/components/Chart/OrigamChartHoneycomb.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-honeycomb--design', '/docs/components/Chart/OrigamChartHoneycomb.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_honeycomb.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"honeycomb chart\")."}, {"noteKey": "components.chart_honeycomb.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing the tile count."}, {"noteKey": "components.chart_honeycomb.a11y.tile_aria", "noteFallback": "Each tile has aria-label derived from its name and value (e.g. \"A: 42\")."}, {"noteKey": "components.chart_honeycomb.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_honeycomb.a11y.key_tab", "actionFallback": "Moves focus through each hex tile (tabindex=\"0\") and legend items."}, {"key": "Enter / Space", "actionKey": "components.chart_honeycomb.a11y.key_activate", "actionFallback": "Activates the focused tile, firing the point-click emit."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"220\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"28\" width=\"636\" height=\"16\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"350\" y=\"40\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header (title)</text>\n  <polygon points=\"140,95 165,81 190,95 190,122 165,136 140,122\" fill=\"var(--origam-color__action--primary---bg, rgba(124,58,237,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"165\" y=\"110\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">A</text>\n  <polygon points=\"193,95 218,81 243,95 243,122 218,136 193,122\" fill=\"var(--origam-color__feedback--success---bg, rgba(34,197,94,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"218\" y=\"110\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">B</text>\n  <polygon points=\"246,95 271,81 296,95 296,122 271,136 246,122\" fill=\"var(--origam-color__feedback--warning---bg, rgba(234,179,8,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"271\" y=\"110\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">C</text>\n  <polygon points=\"166,136 191,122 216,136 216,163 191,177 166,163\" fill=\"var(--origam-color__feedback--danger---bg, rgba(239,68,68,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"191\" y=\"151\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">D</text>\n  <polygon points=\"219,136 244,122 269,136 269,163 244,177 219,163\" fill=\"var(--origam-color__feedback--info---bg, rgba(8,145,178,0.8))\" stroke=\"var(--origam-color__surface---raised,#fff)\" stroke-width=\"2\"/>\n  <text x=\"244\" y=\"151\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-family=\"''JetBrains Mono'',monospace\">E</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"148\" cy=\"103\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"107\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"165\" cy=\"115\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"165\" y=\"119\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"165\" cy=\"132\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"165\" y=\"136\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"36\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"40\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <text x=\"350\" y=\"245\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② tile polygon — points computed by tileSize × orientation; ③ label centred at (cx, cy)</text>\n", "code": "<div class=\"origam-chart-honeycomb\" role=\"figure\" aria-label=\"Hex tile map\">\n  <header class=\"origam-chart-honeycomb__header\">\n    <div class=\"origam-chart-honeycomb__title\">Hex tile map</div>\n  </header>\n\n  <div class=\"origam-chart-honeycomb__body\">\n    <svg class=\"origam-chart-honeycomb__svg origam-chart__svg\" role=\"img\">\n      <title>Hex tile map</title>\n      <desc>Honeycomb chart with 6 tiles.</desc>\n\n      <g class=\"origam-chart__honeycomb-series\">\n        <!-- one group per tile -->\n        <g class=\"origam-chart__honeycomb-tile-group\">\n          <!-- hex polygon (keyboard activatable) -->\n          <polygon\n            class=\"origam-chart__honeycomb-tile\"\n            points=\"…\"\n            tabindex=\"0\"\n            role=\"button\"\n            aria-label=\"A\"\n          />\n          <!-- centred label -->\n          <text class=\"origam-chart__honeycomb-label\">A</text>\n        </g>\n      </g>\n    </svg>\n\n    <!-- tooltip (showTooltip=true) -->\n    <origam-chart-tooltip />\n  </div>\n\n  <!-- legend (showLegend=true) -->\n  <origam-chart-legend />\n</div>", "legend": [{"cls": ".origam-chart-honeycomb", "num": 1, "descriptionKey": "components.chart_honeycomb.anatomy.root", "descriptionFallback": "Root element. CSS grid with areas: header / body / legend. role=\"figure\" + aria-label from title."}, {"cls": ".origam-chart__honeycomb-tile", "num": 2, "descriptionKey": "components.chart_honeycomb.anatomy.tile", "descriptionFallback": "SVG <polygon> for each tile. Points computed from tileSize, col/row index and orientation. tabindex=\"0\" + role=\"button\"."}, {"cls": ".origam-chart__honeycomb-label", "num": 3, "descriptionKey": "components.chart_honeycomb.anatomy.label", "descriptionFallback": "Text centred at the tile''s (cx, cy). Shows name or formatted value. Hidden when showLabel=false."}, {"cls": ".origam-chart__honeycomb-tile--active", "num": 4, "descriptionKey"