hart_honeycomb.anatomy.mod_pointy", "descriptionFallback": "Modifier for pointy-top orientation."}, {"cls": "origam-chart-honeycomb--flat-top", "descriptionKey": "components.chart_honeycomb.anatomy.mod_flat", "descriptionFallback": "Modifier for flat-top orientation."}, {"cls": "origam-chart-honeycomb--categorical", "descriptionKey": "components.chart_honeycomb.anatomy.mod_categorical", "descriptionFallback": "Modifier for categorical colour mode."}, {"cls": "origam-chart-honeycomb--heatmap", "descriptionKey": "components.chart_honeycomb.anatomy.mod_heatmap", "descriptionFallback": "Modifier for heatmap colour mode."}, {"cls": "origam-chart-honeycomb--no-animation", "descriptionKey": "components.chart_honeycomb.anatomy.mod_no_animation", "descriptionFallback": "Disables entry animation."}], "svgDesc": "Schematic of the ChartHoneycomb component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamChartHoneycomb", "rootClass": "origam-chart-honeycomb", "figcaption": "Anatomy of <code>&lt;origam-chart-honeycomb&gt;</code> — 5 internal parts. Hexagon points computed in JavaScript from <code>tileSize</code> and <code>orientation</code>.", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-chart---gap", "defaultValue": "12px", "descriptionKey": "components.chart_honeycomb.css_vars.gap", "descriptionFallback": "Gap between header, body and legend areas."}, {"name": "--origam-chart---padding", "defaultValue": "12px", "descriptionKey": "components.chart_honeycomb.css_vars.padding", "descriptionFallback": "Internal padding of the chart root."}, {"name": "--origam-chart---animation-duration", "defaultValue": "600ms", "descriptionKey": "components.chart_honeycomb.css_vars.animation_duration", "descriptionFallback": "Entry animation duration. Driven by animationDuration prop."}, {"name": "--origam-chart__honeycomb---stroke-color", "defaultValue": "var(--origam-color-surface-default, #ffffff)", "descriptionKey": "components.chart_honeycomb.css_vars.stroke_color", "descriptionFallback": "Stroke colour applied to each tile polygon (creates gap between tiles)."}, {"name": "--origam-chart__honeycomb---stroke-width", "defaultValue": "2", "descriptionKey": "components.chart_honeycomb.css_vars.stroke_width", "descriptionFallback": "Stroke width of tile polygons."}, {"name": "--origam-chart__honeycomb-label---font-size", "defaultValue": "0.625rem", "descriptionKey": "components.chart_honeycomb.css_vars.label_font_size", "descriptionFallback": "Font size of the centred tile label."}, {"name": "--origam-chart__honeycomb-label---font-weight", "defaultValue": "600", "descriptionKey": "components.chart_honeycomb.css_vars.label_font_weight", "descriptionFallback": "Font weight of the centred tile label."}, {"name": "--origam-chart__honeycomb-label---color", "defaultValue": "#ffffff", "descriptionKey": "components.chart_honeycomb.css_vars.label_color", "descriptionFallback": "Fill colour of the centred tile label."}, {"name": "--origam-chart__title---font-size", "defaultValue": "1.125rem", "descriptionKey": "components.chart_honeycomb.css_vars.title_font_size", "descriptionFallback": "Font size of the chart title."}], "playground": {"controls": [{"kind": "select", "prop": "bgColor", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.chart_honeycomb.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "text", "prop": "title", "labelKey": "components.chart_honeycomb.playground.title", "defaultValue": "", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.chart_honeycomb.playground.subtitle", "defaultValue": "", "labelFallback": "Subtitle"}, {"kind": "switch", "prop": "showLabel", "labelKey": "component