."}, {"key": "Enter", "actionKey": "components.data_table_row.a11y.key_expand", "actionFallback": "Toggles row expansion via the expand Btn (when the expand column is present)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-data-table-row---background-color", "descriptionKey": "components.data_table_row.tokens.background_color", "descriptionFallback": "Default row background."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-data-table__row---hover-background-color", "descriptionKey": "components.data_table_row.tokens.hover_background_color", "descriptionFallback": "Row background on hover."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-data-table-row---transition-duration", "descriptionKey": "components.data_table_row.tokens.transition_duration", "descriptionFallback": "Row background transition duration."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-data-table-row__column-title---font-weight", "descriptionKey": "components.data_table_row.tokens.column_title_font_weight", "descriptionFallback": "Column label weight in mobile stacked layout."}, {"type": "dimension", "value": "52px", "tokenPath": "--origam-data-table__row---mobile-column-min-height", "descriptionKey": "components.data_table_row.tokens.mobile_column_min_height", "descriptionFallback": "Minimum cell height in mobile stacked layout."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"24\" width=\"528\" height=\"48\" rx=\"0\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"16\" y=\"72\" width=\"528\" height=\"1\"