ext-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"76\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"412\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"412\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"33\" y1=\"32\" x2=\"300\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"304\" y=\"13\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-data-table-row</text>\n", "code": "<tr class=\"origam-data-table-row\" :aria-selected=\"isSelected([item]) || undefined\">\n  <!-- select column -->\n  <origam-data-table-column-cell class=\"origam-data-table-row__column origam-data-table-row__column--select-row\">\n    <origam-checkbox-btn :model-value=\"isSelected([item])\" @click=\"toggleSelect(item)\" />\n  </origam-data-table-column-cell>\n  <!-- data columns -->\n  <origam-data-table-column-cell v-for=\"column in columns\" class=\"origam-data-table-row__column\">\n    <!-- mobile: show column title + value -->\n    <div class=\"origam-data-table-row__column-title\">{{ column.title }}</div>\n    <div class=\"origam-data-table-row__column-value\">\n      <slot :name=\"`item.${column.key}`\">{{ displayValue }}</slot>\n    </div>\n  </origam-data-table-column-cell>\n  <!-- expand column -->\n  <origam-data-table-column-cell class=\"origam-data-table-row__column origam-data-table-row__column--expanded-row\">\n    <origam-btn :icon=\"isExpanded(item) ? MDI_ICONS.CHEVRON_UP : MDI_ICONS.CHEVRON_DOWN\" @click=\"toggleExpand(item)\" />\n  </origam-data-table-column-cell>\n</tr>", "legend": [{"cls": ".origam-data-table-row", "num": 1, "descriptionKey": "components.data_table_row.anatomy.root", "descriptionFallback": "Root <code>&lt;tr&gt;</code> element. Has <code>--clickable</code> BEM modifier when onClick/onContextmenu/onDblclick listeners are attached. Has <code>--mobile</code> modifier when in mobile layout."}, {"cls": ".origam-data-table-row__column--select-row", "num": 2, "descriptionKey": "components.data_table_row.anatomy.select_column", "descriptionFallback": "Column cell modifier for the data-table-select column. Renders an <code>OrigamCheckboxBtn</code>. In mobile layout uses <code>grid-template-columns: 0; justify-content: end</code>."}, {"cls": ".origam-data-table-row__column", "num": 3, "descriptionKey": "components.data_table_row.anatomy.column", "descriptionFallback": "Generic column cell class applied to each <code>OrigamDataTableColumnCell</code>. In mobile mode wraps title and value in a 2-column grid."}, {"cls": ".origam-data-table-row__column--expanded-row", "num": 4, "descriptionKey": "components.data_table_row.anatomy.expand_column", "descriptionFallback": "Column cell modifier for the data-table-expand column. Renders an expand/collapse <code>OrigamBtn</code> with aria-expanded. In mobile layout uses <code>grid-template-columns: 0; justify-content: center</code>."}], "classes": [{"cls": "origam-data-table-row", "descriptionKey": "components.data_table_row.anatomy.root", "descriptionFallback": "Root tr element."}, {"cls": "origam-data-table-row--clickable", "descriptionKey": "components.data_table_row.anatomy.clickable", "descriptionFallback": "Applied when the tr has click/contextmenu/dblclick listeners. Sets cursor: pointer."}, {"cls": "origam-data-table-row--mobile", "descriptionKey": "components.data_table_row.anatomy.mobile", "descriptionFallback": "Applied in mobile layout. Switches cells to a 2-column grid (title left, value right)."}, {"cls": "origam-data-table-row__column", "descriptionKey": "components.data_table_row.anatomy.column", "descriptionFallback": "Applied to each column cell td."}, {"cls": "origam-data-table-row__column--select-row", "descriptionKey": "components.data_table_row.anatomy.select_row", "descriptionFallback": "Modifier for the selection checkbox column."}, {"cls": "origam-data-table-row__column--expanded-row", "descriptionKey": "components.data_table_row.anatomy.expanded_row", "descriptionFallback": "Modifier for the expand toggle column."}, {"cls": "origam-data-table-row__column-title", "descriptionKey": "components.data_table_row.anatomy.column_title", "descriptionFallback": "Column label shown in mobile layout (left cell). Font-weight: medium."}, {"cls": "origam-data-table-row__column-value", "descriptionKey": "components.data_table_row.anatomy.column_value", "descriptionFallback": "Column value shown in mobile layout (right cell, text-align: right)."}], "svgDesc": "Schematic of DataTableRow with 4 internal parts.", "svgTitle": "Anatomy of OrigamDataTableRow", "rootClass": "origam-data-table-row", "figcaption": "Anatomy of <code>&lt;origam-data-table-row&gt;</code> — 4 parts: tr root ①, select column (CheckboxBtn) ②, data column cell ③, expand column (Btn) ④.", "svgViewBox": "0 0 560 120"}, "cssVars": [{"name": "--origam-data-table-row---background-color", "defaultValue": "var(--origam-color__surface---default)", "descriptionKey": "components.data_table_row.css_vars.background_color", "descriptionFallback": "Default row background colour."}, {"name": "--origam-data-table-row---color", "defaultValue": "var(--origam-color__text---primary)", "descriptionKey": "components.data_table_row.css_vars.color", "descriptionFallback": "Default row text colour."}, {"name": "--origam-data-table-row--hover---background-color", "defaultValue": "var(--origam-color__surface---overlay)", "descriptionKey": "components.data_table_row.css_vars.hover_background_color", "descriptionFallback": "Row background colour on hover."}, {"name": "--origam-data-table-row---transition-duration", "defaultValue": "100ms", "descriptionKey": "components.data_table_row.css_vars.transition_duration", "descriptionFallback": "Duration of the background-colour transition on hover/select."}, {"name": "--origam-data-table-row---transition-easing", "defaultValue": "cubic-bezier(0.4, 0, 0.2, 1)", "descriptionKey": "components.data_table_row.css_vars.transition_easing", "descriptionFallback": "Easing function for the row background transition."}, {"name": "--origam-data-table-row__column-title---font-weight", "defaultValue": "500", "descriptionKey": "components.data_table_row.css_vars.column_title_font_weight", "descriptionFallback": "Font weight of the column title label in mobile stacked layout."}, {"name": "--origam-data-table-row--mobile__column-min-height", "defaultValue": "52px", "descriptionKey": "components.data_table_row.css_vars.mobile_column_min_height", "descriptionFallback": "Minimum height of each stacked cell in mobile layout."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.data_table_row.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.data_table_row.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.data_table_row.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.data_table_row.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.data_table_row.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.data_table_row.exposed.is_loaded", "descriptionFallback": "True on