{"excerpt": [{"type": "dimension", "value": "40px", "tokenPath": "--origam-date-picker__day---size", "descriptionKey": "components.date_picker_month.tokens.day_size", "descriptionFallback": "Day cell size (height and width)."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_month.tokens.day_selected_bg", "descriptionFallback": "Selected day background colour."}, {"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-date-picker__day---background-color-in-range", "descriptionKey": "components.date_picker_month.tokens.day_in_range_bg", "descriptionFallback": "Background of cells within a date-range selection."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <!-- root -->\n  <rect x=\"40\" y=\"20\" width=\"620\" height=\"240\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- week numbers column -->\n  <rect x=\"40\" y=\"20\" width=\"52\" height=\"240\" rx=\"6\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"66\" y=\"50\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Wk</text>\n  <text x=\"66\" y=\"80\"  font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">22</text>\n  <text x=\"66\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">23</text>\n  <text x=\"66\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">24</text>\n  <text x=\"66\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">25</text>\n  <text x=\"66\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">26</text>\n  <!-- days grid -->\n  <rect x=\"96\" y=\"20\" width=\"564\" height=\"240\" rx=\"0\" fill=\"none\"/>\n  <!-- weekday header row -->\n  <rect x=\"96\" y=\"20\" width=\"564\" height=\"36\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\"/>\n  <text x=\"378\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Lu  Ma  Me  Je  Ve  Sa  Di</text>\n  <!-- day cells sample -->\n  <text x=\"378\" y=\"76\"  font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\"> 1   2   3   4   5   6   7</text>\n  <text x=\"378\" y=\"106\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\"> 8   9  10  11  12  13  14</text>\n  <!-- selected day -->\n  <circle cx=\"312\" cy=\"135\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"312\" y=\"139\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\">15</text>\n  <text x=\"386\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">16  17  18  19  20  21</text>\n  <text x=\"378\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">22  23  24  25  26  27  28</text>\n  <text x=\"346\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">29  30</text>\n  <!-- adjacent days faded -->\n  <text x=\"430\" y=\"200\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #aaa)\" text-anchor=\"middle\" font-family=\"system-ui\" opacity=\"0.5\"> 1   2   3   4</text>\n  <!-- markers -->\n  <circle cx=\"48\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"104\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"104\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"104\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"104\" y=\"60.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"312\" cy=\"118\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"312\" y=\"122.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-date-picker-month\">\n  <!-- optional week numbers column (showWeek=true) -->\n  <div class=\"origam-date-picker-month__weeks\">\n    <div class=\"origam-date-picker-month__day\">&nbsp;</div>\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__day--adjacent\">\n      <span>22</span>\n    </div>\n    <!-- … -->\n  </div>\n\n  <!-- animated day grid (OrigamTransition wraps the inner div) -->\n  <div class=\"origam-date-picker-month__days\">\n    <!-- weekday headers (hidden when hideWeekdays=true) -->\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__weekday\">\n      <span>Lu</span>\n    </div>\n    <!-- … -->\n\n    <!-- day cell -->\n    <div class=\"origam-date-picker-month__day origam-date-picker-month__day--selected\">\n      <origam-btn\n        class=\"origam-date-picker-month__day-btn\"\n        :active=\"item.isSelected\"\n        :border=\"item.isToday\"\n        icon\n        :text=\"item.localized\"\n      />\n    </div>\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-month", "num": 1, "descriptionKey": "components.date_picker_month.anatomy.root", "descriptionFallback": "Root flex container. Display: flex, padding: 0 12px 8px. Hosts the weeks column and the days grid side by side."}, {"cls": ".origam-date-picker-month__weeks", "num": 2, "descriptionKey": "components.date_picker_month.anatomy.weeks", "descriptionFallback": "Optional week-numbers column. Visible when showWeek=true. Uses grid-template-rows: repeat(7, 1fr)."}, {"cls": ".origam-date-picker-month__weekday", "num": 3, "descriptionKey": "components.date_picker_month.anatomy.weekday", "descriptionFallback": "Weekday label cell (Mon, Tue…). Font-size 0.85rem. Hidden when hideWeekdays=true."}, {"cls": ".origam-date-picker-month__day", "num": 4, "descriptionKey": "components.date_picker_month.anatomy.day", "descriptionFallback": "Day cell. 40×40px. Contains the day button. Modifiers: --selected, --today, --adjacent, --hide-adjacent, --week-start, --week-end."}], "classes": [{"cls": "origam-date-picker-month", "descriptionKey": "components.date_picker_month.anatomy.root", "descriptionFallback": "Root flex container."}, {"cls": "origam-date-picker-month__weeks", "descriptionKey": "components.date_picker_month.anatomy.weeks", "descriptionFallback": "Week-numbers column (showWeek=true)."}, {"cls": "origam-date-picker-month__days", "descriptionKey": "components.date_picker_month.anatomy.days", "descriptionFallback": "Day grid — 7-column CSS grid."}, {"cls": "origam-date-picker-month__weekday", "descriptionKey": "components.date_picker_month.anatomy.weekday", "descriptionFallback": "Weekday label header cell."}, {"cls": "origam-date-picker-month__day", "descriptionKey": "components.date_picker_month.anatomy.day", "descriptionFallback": "Day wrapper cell. 40×40px."}, {"cls": "origam-date-picker-month__day--selected", "descriptionKey": "components.date_picker_month.anatomy.day_selected", "descriptionFallback": "Applied when the day is part of the current selection."}, {"cls": "origam-date-picker-month__day--today", "descriptionKey": "components.date_picker_month.anatomy.day_today", "descriptionFallback": "Applied when the day is today. The inner button receives border=true."}, {"cls": "origam-date-picker-month__day--adjacent", "descriptionKey": "components.date_picker_month.anatomy.day_adjacent", "descriptionFallback": "Days from the previous or next month. Opacity 0.5."}, {"cls": "origam-date-picker-month__day--hide-adjacent", "descriptionKey": "components.date_picker_month.anatomy.day_hide_adjacent", "descriptionFallback": "Adjacent days rendered invisible (opacity 0) when showAdjacentMonths=false."}, {"cls": "origam-date-picker-month__day-btn", "descriptionKey": "components.date_picker_month.anatomy.day_btn", "descriptionFallback": "Inner OrigamBtn inside each day cell. Height 24px, font-size 0.85rem."}], "svgDesc": "Schematic of the DatePickerMonth component showing weekday labels, day cells and week numbers column.", "svgTitle": "Anatomy of OrigamDatePickerMonth", "rootClass": "origam-date-picker-month", "figcaption": "Anatomy of <code>&lt;origam-date-picker-month&gt;</code> — 4 parts: ① root wrapper, ② week-numbers column (showWeek), ③ weekday header row, ④ day button cells.", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-date-picker-month-day-diff", "defaultValue": "4px", "descriptionKey": "components.date_picker_month.css_vars.day_diff", "descriptionFallback": "Gap used to offset the range-selection pseudo-element (::before/::after) on selected day cells."}, {"name": "--origam-btn---height", "defaultValue": "24px", "descriptionKey": "components.date_picker_month.css_vars.btn_height", "descriptionFallback": "Height of the inner day button (overridden from the default btn height via :deep selector)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_month.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_month.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_month.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_month.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_month.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_month.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_month.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "hideWeekdays", "labelKey": "components.date_picker_month.playground.hide_weekdays", "defaultValue": false, "labelFallback": "Hide Weekdays"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker_month.playground.range", "defaultValue": false, "labelFallback": "Range"}, {"kind": "switch", "prop": "showWeek", "labelKey": "components.date_picker_month.playground.show_week", "defaultValue": false, "labelFallback": "Show Week"}, {"kind": "switch", "prop": "showAdjacentMonths", "labelKey": "components.date_picker_month.playground.show_adjacent_months", "defaultValue": false, "labelFallback": "Show Adjacent Months"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('501bdaac-1257-4ea8-acf5-31cbec7bee9f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'date-picker-years', 'DatePickerYears', 'Form & Input', NULL, 'mdi-calendar-range', 'components.catalog.date_picker_years.description', 'Scrollable year list for picking a year. Renders years in a 3-column grid from min to max (defaulting to ±100 years from today). Auto-scrolls to the selected year on mount.', NULL, NULL, 'origam-date-picker-years', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerYears.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePickerYears.html', 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_years.a11y.scroll_note", "noteFallback": "On mount, the selected year is automatically scrolled into the centre of the visible area via scrollIntoView({block: \"center\"}), so users do not need to scroll manually to find the current year."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.date_picker_years.a11y.key_select", "actionFallback": "Selects the focused year."}, {"key": "Tab", "actionKey": "components.date_picker_years.a11y.key_tab", "actionFallback": "Moves focus between year tiles."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_years.tokens.selected_bg", "descriptionFallback": "Active year button background (driven by the color prop)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <!-- root with scroll indicator -->\n  <rect x=\"100\" y=\"20\" width=\"500\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- scroll indicator bar on right -->\n  <rect x=\"590\" y=\"20\" width=\"6\" height=\"180\" rx=\"3\" fill=\"var(--origam-color__border---subtle, rgba(0,0,0,0.06))\"/>\n  <rect x=\"590\" y=\"68\" width=\"6\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <!-- 3-col grid -->\n  <text x=\"162\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2020</text>\n  <text x=\"310\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2021</text>\n  <text x=\"458\" y=\"52\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2022</text>\n  <text x=\"162\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2023</text>\n  <text x=\"310\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2024</text>\n  <text x=\"458\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2025</text>\n  <!-- selected year -->\n  <rect x=\"218\" y=\"92\" width=\"184\" height=\"28\" rx=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"310\" y=\"110\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"700\">2026</text>\n  <text x=\"162\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2026</text>\n  <text x=\"458\" y=\"110\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2027</text>\n  <text x=\"162\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2028</text>\n  <text x=\"310\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2029</text>\n  <text x=\"458\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__text---primary, #222)\" text-anchor=\"middle\" font-family=\"system-ui\">2030</text>\n  <text x=\"350\" y=\"178\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">… scrollable</text>\n  <!-- markers -->\n  <circle cx=\"108\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"120\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"120\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"220\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"220\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-years\">\n  <div class=\"origam-date-picker-years__content\">\n    <!-- slot: #year — repeated for each year in the [min..max] range -->\n    <origam-btn\n      v-for=\"year in years\"\n      :ref=\"model === year.value ? yearRef : undefined\"\n      :active=\"model === year.value\"\n      :color=\"model === year.value ? color : undefined\"\n      :rounded=\"true\"\n      :text=\"year.text\"\n      @click=\"handleClick(year.value)\"\n    />\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-years", "num": 1, "descriptionKey": "components.date_picker_years.anatomy.root", "descriptionFallback": "Root container. Height 288px (default), overflow-y: scroll. Enables native browser scrolling to the selected year."}, {"cls": ".origam-date-picker-years__content", "num": 2, "descriptionKey": "components.date_picker_years.anatomy.content", "descriptionFallback": "3-column CSS grid with justify-content: space-around. gap: 8px 24px. padding-inline: 32px. Inner OrigamBtn have padding-inline: 8px."}, {"cls": "OrigamBtn (active)", "num": 3, "descriptionKey": "components.date_picker_years.anatomy.active_btn", "descriptionFallback": "The selected year button. Receives active=true and color=props.color. All buttons have rounded=true. The active button is also assigned a template ref so scrollIntoView can target it on mount."}], "classes": [{"cls": "origam-date-picker-years", "descriptionKey": "components.date_picker_years.anatomy.root", "descriptionFallback": "Root scroll container. Default height 288px."}, {"cls": "origam-date-picker-years__content", "descriptionKey": "components.date_picker_years.anatomy.content", "descriptionFallback": "3-column grid of year buttons."}], "svgDesc": "Schematic of the DatePickerYears component showing a scrollable 3-column grid of year buttons.", "svgTitle": "Anatomy of OrigamDatePickerYears", "rootClass": "origam-date-picker-years", "figcaption": "Anatomy of <code>&lt;origam-date-picker-years&gt;</code> — 3 parts: ① root scroll container (288px height, overflow-y: scroll), ② 3-column grid content wrapper, ③ the active year button. On mount, the selected year scrolls into view via <code>scrollIntoView({block: ''center''})</code>.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-date-picker-years---height", "defaultValue": "288px", "descriptionKey": "components.date_picker_years.css_vars.height", "descriptionFallback": "Container height. Overflow-y: scroll. Overridden via the height prop (IDimensionProps)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_years.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_years.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_years.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_years.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_years.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_years.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_years.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('80e56975-9e6d-4727-adc2-e30ee5ffeb70', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'defaults-provider', 'DefaultsProvider', 'Utilities & Providers', NULL, 'mdi-tune-variant', 'components.catalog.defaults_provider.description', 'Structurally transparent context provider that injects a prop-defaults map into all descendant Origam components via useDefaults().', NULL, NULL, 'origam-defaults-provider', NULL, 'packages/ds/src/components/DefaultsProvider/OrigamDefaultsProvider.vue', 'origam', NULL, NULL, '/stories/?story=components-defaults-provider--design', '/docs/components/DefaultsProvider/OrigamDefaultsProvider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.defaults_provider.a11y.transparent_note", "noteFallback": "OrigamDefaultsProvider has no visual rendering, no focusable element and no ARIA attributes. All a11y considerations belong to the descendant components it wraps."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"120\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"8 4\"/>\n  <text x=\"350\" y=\"30\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">origam-defaults-provider (no DOM output)</text>\n  <rect x=\"80\" y=\"70\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">child component</text>\n  <rect x=\"300\" y=\"70\" width=\"180\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"390\" y=\"104\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">child component</text>\n  <rect x=\"520\" y=\"70\" width=\"120\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"580\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">…more</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"170\" cy=\"78\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"170\" y=\"82.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"185\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① Provider (transparent) injects defaults via provide() — no DOM node rendered</text>\n", "code": "<!-- OrigamDefaultsProvider renders ONLY its default slot — no DOM wrapper -->\n<template>\n  <slot name=\"default\" />\n</template>\n\n<script setup>\n// Injects the defaults map into all useDefaults() consumers in the subtree\nprovideDefaults(computed(() => props.defaults ?? {}), {\n  scoped: props.scoped,\n  reset: props.reset,\n  root: props.root,\n  disabled: props.disabled\n})\n</script>", "legend": [{"cls": ".origam-defaults-provider (no DOM)", "num": 1, "descriptionKey": "components.defaults_provider.anatomy.provider", "descriptionFallback": "The provider itself. Calls <code>provideDefaults()</code> once on setup, then renders only <code>&lt;slot name=\"default\"/&gt;</code>. No wrapper element is injected into the DOM."}, {"cls": "#default slot — descendant components", "num": 2, "descriptionKey": "components.defaults_provider.anatomy.slot", "descriptionFallback": "Any Origam component in the subtree that calls <code>useDefaults()</code> automatically picks up the injected map. Child components are NOT aware of being wrapped."}], "classes": [{"cls": "origam-defaults-provider", "descriptionKey": "components.defaults_provider.anatomy.root", "descriptionFallback": "No CSS class is emitted on any DOM element. The component is purely logical."}], "svgDesc": "Schematic showing the provider renders only its default slot with no visual chrome.", "svgTitle": "Anatomy of OrigamDefaultsProvider", "rootClass": "origam-defaults-provider", "figcaption": "Anatomy of <code>&lt;origam-defaults-provider&gt;</code> — structurally transparent. The component renders only the <code>#default</code> slot; it injects defaults via Vue''s <code>provide()</code> / <code>inject()</code> without any DOM output of its own.", "svgViewBox": "0 0 700 200"}, "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.defaults_provider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component. Used by Origam''s auto-forwarding pattern."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.defaults_provider.playground.disabled", "defaultValue": false, "labelFallback": "Disabled (pass through parent defaults)"}, {"kind": "switch", "prop": "scoped", "labelKey": "components.defaults_provider.playground.scoped", "defaultValue": false, "labelFallback": "Scoped (no parent inheritance)"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('035259ef-cc06-4b8e-930b-b24b9f568220', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'dialog', 'Dialog', 'Overlay & Surface', NULL, 'mdi-card-outline', 'components.catalog.dialog.description', 'Modal overlay dialog built on OrigamOverlay and OrigamCard. Supports activator slot, focus trap, scrollable mode, fullscreen, size variants, and status icons.', NULL, NULL, 'origam-dialog', NULL, 'packages/ds/src/components/Dialog/OrigamDialog.vue', 'origam', NULL, NULL, '/stories/?story=components-dialog--design', '/docs/components/Dialog/OrigamDialog.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.dialog.a11y.role_note", "noteFallback": "The inner OrigamCard renders role=\"dialog\" and aria-modal=\"true\". The title element is linked via aria-labelledby using the auto-generated dialogTitleId."}, {"noteKey": "components.dialog.a11y.focus_note", "noteFallback": "On open, focus moves to the overlay content element. On close, focus returns to the activator element."}, {"noteKey": "components.dialog.a11y.activator_note", "noteFallback": "The activator element automatically receives aria-haspopup=\"dialog\" and aria-expanded bound to the open state."}, {"noteKey": "components.dialog.a11y.persistent_note", "noteFallback": "When persistent=true, Escape and click-outside do not close the dialog. Use this only for critical flows (e.g., unsaved changes warning)."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.dialog.a11y.key_escape", "actionFallback": "Closes the dialog (unless persistent=true)."}, {"key": "Tab", "actionKey": "components.dialog.a11y.key_tab", "actionFallback": "Cycles focus through focusable elements inside the dialog. When retainFocus=true, Tab wraps from last to first element."}, {"key": "Shift+Tab", "actionKey": "components.dialog.a11y.key_shift_tab", "actionFallback": "Cycles focus backwards. Wraps from first to last element when retainFocus=true."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-dialog---background", "descriptionKey": "components.dialog.tokens.background", "descriptionFallback": "Dialog surface background. Uses the raised surface semantic color."}, {"type": "dimension", "value": "var(--origam-radius---lg)", "tokenPath": "--origam-dialog---border-radius", "descriptionKey": "components.dialog.tokens.border_radius", "descriptionFallback": "Border radius applied to the dialog content wrapper. Reset to 0 in fullscreen mode."}, {"type": "shadow", "value": "var(--origam-shadow---xl)", "tokenPath": "--origam-dialog---box-shadow", "descriptionKey": "components.dialog.tokens.box_shadow", "descriptionFallback": "Elevation shadow for the dialog surface."}, {"type": "number", "value": "var(--origam-zIndex---modal)", "tokenPath": "--origam-dialog---z-index", "descriptionKey": "components.dialog.tokens.z_index", "descriptionFallback": "z-index of the dialog overlay (default: 2400)."}, {"type": "dimension", "value": "720px", "tokenPath": "--origam-dialog---width-md", "descriptionKey": "components.dialog.tokens.width_md", "descriptionFallback": "Default dialog width (size=\"default\")."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-dialog---transition-duration", "descriptionKey": "components.dialog.tokens.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-dialog__header---padding", "descriptionKey": "components.dialog.tokens.header_padding", "descriptionFallback": "Padding inside the dialog header zone."}, {"type": "dimension", "value": "var(--origam-space---6)", "tokenPath": "--origam-dialog__content---padding-inline", "descriptionKey": "components.dialog.tokens.content_padding_inline", "descriptionFallback": "Horizontal padding of the dialog body content."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- overlay scrim -->\n  <rect x=\"10\" y=\"10\" width=\"680\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.08)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"25\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">origam-overlay (scrim)</text>\n  <!-- card surface -->\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"220\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- header zone -->\n  <rect x=\"100\" y=\"40\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"72\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">header — prepend | title | subtitle | append (close btn)</text>\n  <!-- content zone -->\n  <rect x=\"100\" y=\"96\" width=\"500\" height=\"108\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"155\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot + isRead sentinel</text>\n  <!-- footer zone -->\n  <rect x=\"100\" y=\"204\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"236\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">footer — action buttons</text>\n  <!-- numbering -->\n  <circle cx=\"18\" cy=\"18\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"18\" y=\"22.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"104\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"108.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"212\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"216.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<origam-overlay v-model=\"isActive\" class=\"origam-dialog\">\n  <!-- activator trigger element -->\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n\n  <template #default=\"{ isActive }\">\n    <slot name=\"default\" v-bind=\"{ isActive }\">\n      <!-- default body: OrigamCard -->\n      <origam-card\n        role=\"dialog\"\n        aria-modal=\"true\"\n        :aria-labelledby=\"dialogTitleId\"\n      >\n        <!-- header zone: prepend | title | subtitle | append(close) -->\n        <template #header-prepend><slot name=\"header-prepend\" /></template>\n        <template #header-title=\"{ titleId }\"><slot name=\"header-title\" v-bind=\"{ titleId }\" /></template>\n        <template #header-append>\n          <slot name=\"header-append\">\n            <origam-btn icon=\"mdi-close\" @click=\"handleClose\" aria-label=\"Close dialog\" />\n          </slot>\n        </template>\n\n        <!-- scrollable content body -->\n        <template #default>\n          <slot name=\"content\" />\n          <div ref=\"endText\" v-intersect=\"handleIntersect\" />\n        </template>\n\n        <!-- footer actions -->\n        <template #footer><slot name=\"footer\" /></template>\n      </origam-card>\n    </slot>\n  </template>\n</origam-overlay>", "legend": [{"cls": ".origam-overlay (scrim)", "num": 1, "descriptionKey": "components.dialog.anatomy.overlay", "descriptionFallback": "Full-viewport overlay managed by OrigamOverlay. Blocks interaction with the page and handles click-outside / Escape key."}, {"cls": ".origam-card (header)", "num": 2, "descriptionKey": "components.dialog.anatomy.header", "descriptionFallback": "Card header zone with prepend (status icon), title (aria-labelledby target), subtitle, and append (close button)."}, {"cls": ".origam-card__content", "num": 3, "descriptionKey": "components.dialog.anatomy.content", "descriptionFallback": "Scrollable content body. Contains the #content slot plus an invisible IntersectionObserver sentinel that fires isRead when scrolled into view."}, {"cls": ".origam-card__footer", "num": 4, "descriptionKey": "components.dialog.anatomy.footer", "descriptionFallback": "Footer area for action buttons. Typically Cancel and Confirm. Fixed at the bottom in scrollable mode."}], "classes": [{"cls": "origam-dialog", "descriptionKey": "components.dialog.anatomy.root", "descriptionFallback": "Root class applied to the origam-overlay element. Drives alignment (center center) and size-width vars."}, {"cls": "origam-dialog--fullscreen", "descriptionKey": "components.dialog.anatomy.fullscreen", "descriptionFallback": "Applied when fullscreen=true. Resets width, max-width, max-height and border-radius to 100vw/100vh/0."}, {"cls": "origam-dialog--scrollable", "descriptionKey": "components.dialog.anatomy.scrollable", "descriptionFallback": "Applied when scrollable=true. Enables overflow-y: auto on the card content zone."}, {"cls": "origam-dialog--size-x-small", "descriptionKey": "components.dialog.anatomy.size_xs", "descriptionFallback": "Sets --origam-dialog---width to 320px."}, {"cls": "origam-dialog--size-small", "descriptionKey": "components.dialog.anatomy.size_sm", "descriptionFallback": "Sets --origam-dialog---width to 400px."}, {"cls": "origam-dialog--size-default", "descriptionKey": "components.dialog.anatomy.size_md", "descriptionFallback": "Sets --origam-dialog---width to 720px."}, {"cls": "origam-dialog--size-large", "descriptionKey": "components.dialog.anatomy.size_lg", "descriptionFallback": "Sets --origam-dialog---width to 960px."}, {"cls": "origam-dialog--size-x-large", "descriptionKey": "components.dialog.anatomy.size_xl", "descriptionFallback": "Sets --origam-dialog---width to 1080px."}], "svgDesc": "Schematic of the Dialog component showing overlay wrapper, card body, header, content, and footer zones.", "svgTitle": "Anatomy of OrigamDialog", "rootClass": "origam-dialog", "figcaption": "Anatomy of <code>&lt;origam-dialog&gt;</code> — 4 zones: ① overlay scrim, ② card header (prepend / title / append), ③ scrollable content body, ④ footer for actions.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-dialog---width", "defaultValue": "auto", "descriptionKey": "components.dialog.css_vars.width", "descriptionFallback": "Dialog width. Overridden per size class (xs: 320px → xl: 1080px) and set to 100vw in fullscreen mode."}, {"name": "--origam-dialog---max-height", "defaultValue": "calc(100vh - 48px)", "descriptionKey": "components.dialog.css_vars.max_height", "descriptionFallback": "Maximum dialog height. Resolves to 100vh in fullscreen mode."}, {"name": "--origam-dialog---max-width", "defaultValue": "calc(100vw - 48px)", "descriptionKey": "components.dialog.css_vars.max_width", "descriptionFallback": "Maximum dialog width."}, {"name": "--origam-dialog---border-radius", "defaultValue": "{radius.lg} (12px)", "descriptionKey": "components.dialog.css_vars.border_radius", "descriptionFallback": "Border radius applied to the overlay content wrapper. Reset to 0 in fullscreen mode."}, {"name": "--origam-dialog---box-shadow", "defaultValue": "{shadow.xl}", "descriptionKey": "components.dialog.css_vars.box_shadow", "descriptionFallback": "Box shadow applied to the dialog surface for depth."}, {"name": "--origam-dialog---width-xs", "defaultValue": "320px", "descriptionKey": "components.dialog.css_vars.width_xs", "descriptionFallback": "Width token for size=\"x-small\"."}, {"name": "--origam-dialog---width-sm", "defaultValue": "400px", "descriptionKey": "components.dialog.css_vars.width_sm", "descriptionFallback": "Width token for size=\"small\"."}, {"name": "--origam-dialog---width-md", "defaultValue": "720px", "descriptionKey": "components.dialog.css_vars.width_md", "descriptionFallback": "Width token for size=\"default\"."}, {"name": "--origam-dialog---width-lg", "defaultValue": "960px", "descriptionKey": "components.dialog.css_vars.width_lg", "descriptionFallback": "Width token for size=\"large\"."}, {"name": "--origam-dialog---width-xl", "defaultValue": "1080px", "descriptionKey": "components.dialog.css_vars.width_xl", "descriptionFallback": "Width token for size=\"x-large\"."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.dialog.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to inner OrigamOverlay or OrigamCard instances."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.dialog.exposed.css", "descriptionFallback": "Reactive CSS string generated from dialogStyles. Used by OrigamDefaultsProvider for style injection."}, {"name": "id", "type": "string", "descriptionKey": "components.dialog.exposed.id", "descriptionFallback": "Unique style-sheet ID for this dialog instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.dialog.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.dialog.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.dialog.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "contentEl", "type": "HTMLElement | undefined", "descriptionKey": "components.dialog.exposed.content_el", "descriptionFallback": "Reference to the overlay content element forwarded from the inner OrigamOverlay ref."}, {"name": "activatorEl", "type": "HTMLElement | undefined", "descriptionKey": "components.dialog.exposed.activator_el", "descriptionFallback": "Reference to the activator element forwarded from the inner OrigamOverlay ref."}, {"name": "globalTop", "type": "boolean", "descriptionKey": "components.dialog.exposed.global_top", "descriptionFallback": "True when this dialog is the topmost open overlay in the global stack."}], "playground": {"controls": [{"kind": "select", "prop": "size", "options": [{"label": "x-small (320px)", "value": "x-small"}, {"label": "small (400px)", "value": "small"}, {"label": "default (720px)", "value": "default"}, {"label": "large (960px)", "value": "large"}, {"label": "x-large (1080px)", "value": "x-large"}], "labelKey": "components.dialog.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.dialog.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}, {"kind": "switch", "prop": "scrollable", "labelKey": "components.dialog.playground.scrollable", "defaultValue": false, "labelFallback": "Scrollable"}, {"kind": "switch", "prop": "persistent", "labelKey": "components.dialog.playground.persistent", "defaultValue": false, "labelFallback": "Persistent (no outside-click close)"}, {"kind": "select", "prop": "status", "options": [{"label": "(none)", "value": ""}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.dialog.playground.status", "defaultValue": "", "labelFallback": "Status"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e68378e1-1aff-4a0f-a6bc-6fa63bf6166f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'dialog-confirmation', 'DialogConfirmation', 'Overlay & Surface', NULL, 'mdi-check-circle-outline', 'components.catalog.dialog_confirmation.description', 'Opinionated dialog with built-in Validate / Cancel footer buttons and a read-to-enable guard — the Validate button is only enabled once the user has scrolled to the bottom of the content (isRead pattern).', NULL, NULL, 'origam-dialog-confirmation', NULL, 'packages/ds/src/components/Dialog/OrigamDialogConfirmation.vue', 'origam', NULL, NULL, '/stories/?story=components-dialog--design', '/docs/components/Dialog/OrigamDialogConfirmation.html', 'dialog', '{"a11y": {"notes": [{"noteKey": "components.dialog_confirmation.a11y.validate_disabled_note", "noteFallback": "The Validate button is rendered with disabled=true and aria-disabled until the user scrolls to the bottom of the content (isRead=true). This is intentional — it enforces that users read critical content before confirming."}, {"noteKey": "components.dialog_confirmation.a11y.role_note", "noteFallback": "role=\"dialog\" and aria-modal=\"true\" are applied by the inner OrigamDialog on the card element. The title is linked via aria-labelledby."}, {"noteKey": "components.dialog_confirmation.a11y.focus_note", "noteFallback": "On open, focus moves to the overlay content. On close, focus returns to the activator element."}], "roles": ["dialog"], "keyboard": [{"key": "Escape", "actionKey": "components.dialog_confirmation.a11y.key_escape", "actionFallback": "Closes the dialog (unless persistent=true)."}, {"key": "Tab", "actionKey": "components.dialog_confirmation.a11y.key_tab", "actionFallback": "Cycles focus through Cancel, Validate and any other focusable elements inside the dialog (focus trap inherited from OrigamDialog)."}, {"key": "Shift+Tab", "actionKey": "components.dialog_confirmation.a11y.key_shift_tab", "actionFallback": "Cycles focus backwards."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- overlay scrim -->\n  <rect x=\"10\" y=\"10\" width=\"680\" height=\"280\" rx=\"4\" fill=\"rgba(0,0,0,0.08)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"24\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">OrigamDialog (inner overlay)</text>\n  <!-- card surface -->\n  <rect x=\"100\" y=\"36\" width=\"500\" height=\"228\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- header zone -->\n  <rect x=\"100\" y=\"36\" width=\"500\" height=\"56\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"68\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">header — prepend (status icon) | title | append (close)</text>\n  <!-- content zone -->\n  <rect x=\"100\" y=\"92\" width=\"500\" height=\"100\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.12))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"146\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#content slot + isRead IntersectionObserver sentinel</text>\n  <!-- footer zone -->\n  <rect x=\"100\" y=\"192\" width=\"500\" height=\"72\" rx=\"8\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.18))\" stroke-width=\"1\"/>\n  <!-- cancel button -->\n  <rect x=\"120\" y=\"212\" width=\"100\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\"/>\n  <text x=\"170\" y=\"232\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"system-ui\">Cancel</text>\n  <!-- validate button -->\n  <rect x=\"468\" y=\"212\" width=\"112\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"524\" y=\"232\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"600\">Validate</text>\n  <text x=\"350\" y=\"247\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">Validate enabled only when isRead = true (user scrolled to bottom)</text>\n  <!-- markers -->\n  <circle cx=\"18\" cy=\"18\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"18\" y=\"22.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"108\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"108\" cy=\"100\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"104.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"200\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"108\" y=\"204.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<origam-dialog\n  ref=\"origamDialogRef\"\n  v-model=\"isActive\"\n  v-bind=\"dialogProps\"\n  @is-read=\"handleIsRead\"\n>\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n\n  <!-- all header-* slots forwarded -->\n  <template #header><slot name=\"header\" /></template>\n  <template #header-prepend><slot name=\"header-prepend\" /></template>\n  <template #header-title><slot name=\"header-title\" /></template>\n  <!-- … -->\n\n  <template #content><slot name=\"content\" /></template>\n\n  <!-- built-in footer: Cancel + Validate -->\n  <template #footer>\n    <slot name=\"footer\">\n      <origam-container fluid>\n        <origam-row justify=\"space-between\">\n          <origam-col cols=\"auto\">\n            <origam-btn v-if=\"cancellable\" text=\"Cancel\" @click=\"handleCancel\" />\n          </origam-col>\n          <origam-col cols=\"auto\">\n            <origam-btn :disabled=\"!validatable\" text=\"Validate\" @click=\"handleValidate\" />\n          </origam-col>\n        </origam-row>\n      </origam-container>\n    </slot>\n  </template>\n</origam-dialog>", "legend": [{"cls": ".origam-overlay (scrim)", "num": 1, "descriptionKey": "components.dialog_confirmation.anatomy.overlay", "descriptionFallback": "Full-viewport overlay inherited from OrigamDialog. Handles click-outside and Escape (unless persistent=true)."}, {"cls": ".origam-card (header)", "num": 2, "descriptionKey": "components.dialog_confirmation.anatomy.header", "descriptionFallback": "Card header with status icon in prepend slot, title, and close button in append slot. All header-* slots are forwarded transparently."}, {"cls": ".origam-card__content", "num": 3, "descriptionKey": "components.dialog_confirmation.anatomy.content", "descriptionFallback": "Scrollable content body. An IntersectionObserver sentinel at the bottom fires the @isRead event when it enters the viewport, enabling the Validate button."}, {"cls": ".origam-card__footer (two-button bar)", "num": 4, "descriptionKey": "components.dialog_confirmation.anatomy.footer", "descriptionFallback": "Default footer with Cancel (left) and Validate (right) in a space-between row. The Validate button is disabled until isRead=true. Override with the #footer slot."}], "classes": [{"cls": "origam-dialog", "descriptionKey": "components.dialog_confirmation.anatomy.root", "descriptionFallback": "Root class — delegated to the inner OrigamDialog. DialogConfirmation itself has no additional BEM root class."}], "svgDesc": "Schematic of the DialogConfirmation component showing its inner OrigamDialog with header, content, and a two-button footer.", "svgTitle": "Anatomy of OrigamDialogConfirmation", "rootClass": "origam-dialog", "figcaption": "Anatomy of <code>&lt;origam-dialog-confirmation&gt;</code> — wraps OrigamDialog with 4 zones: ① overlay scrim, ② header (status icon + title), ③ scrollable content + isRead sentinel, ④ two-button footer (Cancel / Validate).", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-dialog-confirmation---icon-size", "defaultValue": "28px", "descriptionKey": "components.dialog_confirmation.css_vars.icon_size", "descriptionFallback": "Size of the status icon in the header prepend slot."}, {"name": "--origam-dialog-confirmation---icon-color-default", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_default", "descriptionFallback": "Icon colour when no status is set."}, {"name": "--origam-dialog-confirmation---icon-color-success", "defaultValue": "{color.feedback.success.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_success", "descriptionFallback": "Icon colour when status=\"success\"."}, {"name": "--origam-dialog-confirmation---icon-color-warning", "defaultValue": "{color.feedback.warning.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_warning", "descriptionFallback": "Icon colour when status=\"warning\"."}, {"name": "--origam-dialog-confirmation---icon-color-danger", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_danger", "descriptionFallback": "Icon colour when status=\"danger\"."}, {"name": "--origam-dialog-confirmation---icon-color-info", "defaultValue": "{color.feedback.info.fgSubtle}", "descriptionKey": "components.dialog_confirmation.css_vars.icon_color_info", "descriptionFallback": "Icon colour when status=\"info\"."}, {"name": "--origam-dialog-confirmation---title-font-size", "defaultValue": "{font.size.lg}", "descriptionKey": "components.dialog_confirmation.css_vars.title_font_size", "descriptionFallback": "Title font size."}, {"name": "--origam-dialog-confirmation---title-font-weight", "defaultValue": "{font.weight.semibold}", "descriptionKey": "components.dialog_confirmation.css_vars.title_font_weight", "descriptionFallback": "Title font weight."}, {"name": "--origam-dialog-confirmation---actions-gap", "defaultValue": "{space.3}", "descriptionKey": "components.dialog_confirmation.css_vars.actions_gap", "descriptionFallback": "Gap between footer action buttons."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.dialog_confirmation.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the inner OrigamDialog."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.dialog_confirmation.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "size", "options": [{"label": "(default)", "value": ""}, {"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.dialog_confirmation.playground.size", "defaultValue": "", "labelFallback": "Size"}, {"kind": "select", "prop": "status", "options": [{"label": "(default)", "value": ""}, {"label": "STATUS.SUCCESS", "value": "STATUS.SUCCESS"}, {"label": "success", "value": "success"}, {"label": "info", "value": "info"}, {"label": "STATUS.INFO", "value": "STATUS.INFO"}, {"label": "STATUS.WARNING", "value": "STATUS.WARNING"}, {"label": "warning", "value": "warning"}, {"label": "error", "value": "error"}, {"label": "STATUS.ERROR", "value": "STATUS.ERROR"}], "labelKey": "components.dialog_confirmation.playground.status", "defaultValue": "", "labelFallback": "Status"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.dialog_confirmation.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "modelValue", "labelKey": "components.dialog_confirmation.playground.model_value", "defaultValue": false, "labelFallback": "Value"}, {"kind": "switch", "prop": "cancellable", "labelKey": "components.dialog_confirmation.playground.cancellable", "defaultValue": true, "labelFallback": "Cancellable"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.dialog_confirmation.playground.icon", "defaultValue": "", "labelFallback": "Icon"}, {"kind": "switch", "prop": "fullscreen", "labelKey": "components.dialog_confirmation.playground.fullscreen", "defaultValue": false, "labelFallback": "Fullscreen"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a869d77f-d3dc-465c-a3c1-fb26e43ec191', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'divider', 'Divider', 'Layout & Structure', NULL, 'mdi-minus', 'components.catalog.divider.description', 'Horizontal or vertical separator rendered as a semantic <hr> with color, thickness and inset support.', NULL, NULL, 'origam-divider', NULL, 'packages/ds/src/components/Divider/OrigamDivider.vue', 'origam', NULL, NULL, '/stories/?story=components-divider--design', '/docs/components/Divider/OrigamDivider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.divider.a11y.role_note", "noteFallback": "Renders as a native <hr> element which has an implicit role=\"separator\". The aria-orientation attribute matches the direction prop (horizontal or vertical)."}, {"noteKey": "components.divider.a11y.decorative_note", "noteFallback": "When used purely for visual decoration, pass role=\"presentation\" via attrs to remove the element from the accessibility tree."}], "roles": ["separator"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-divider---color", "descriptionKey": "components.divider.tokens.color", "descriptionFallback": "Default divider color. References the subtle border semantic token."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-divider---thickness", "descriptionKey": "components.divider.tokens.thickness", "descriptionFallback": "Default stroke thickness. Overridden by the thickness prop."}, {"type": "number", "value": "var(--origam-opacity---100)", "tokenPath": "--origam-divider---opacity", "descriptionKey": "components.divider.tokens.opacity", "descriptionFallback": "Token default opacity (1). SCSS overrides to 0.12 for a subtle separator effect."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--origam-divider---margin-block", "descriptionKey": "components.divider.tokens.margin_block", "descriptionFallback": "Default block margin (0). Use the margin prop for spacing."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"350\" y=\"40\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">HORIZONTAL</text>\n  <rect x=\"40\" y=\"55\" width=\"620\" height=\"2\" rx=\"1\" fill=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <circle cx=\"48\" cy=\"56\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"60.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"350\" y=\"110\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">VERTICAL</text>\n  <rect x=\"348\" y=\"120\" width=\"4\" height=\"60\" rx=\"1\" fill=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <circle cx=\"350\" cy=\"125\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"129.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"195\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Rendered as &lt;hr&gt; — native HTML separator with role=\"separator\"</text>\n", "code": "<hr\n  role=\"separator\"\n  aria-orientation=\"horizontal\"\n  class=\"origam-divider origam-divider--horizontal\"\n/>", "legend": [{"cls": ".origam-divider", "num": 1, "descriptionKey": "components.divider.anatomy.root_horizontal", "descriptionFallback": "Root <code>&lt;hr&gt;</code> element. In horizontal mode: <code>display: block; flex: 1 1 100%</code>. <code>aria-orientation=\"horizontal\"</code>."}, {"cls": ".origam-divider--vertical", "num": 2, "descriptionKey": "components.divider.anatomy.vertical", "descriptionFallback": "Vertical variant modifier. Switches to <code>display: inline-flex</code>, <code>height: auto</code>, <code>align-self: stretch</code>. <code>aria-orientation=\"vertical\"</code>."}, {"cls": ".origam-divider--inset", "num": 3, "descriptionKey": "components.divider.anatomy.inset", "descriptionFallback": "Inset modifier. Adds <code>margin-inline-start</code> so the line aligns with list item content."}], "classes": [{"cls": "origam-divider", "descriptionKey": "components.divider.anatomy.root_horizontal", "descriptionFallback": "Root element. Renders as a semantic <hr> with role=\"separator\"."}, {"cls": "origam-divider--horizontal", "descriptionKey": "components.divider.anatomy.horizontal", "descriptionFallback": "Applied when direction=\"horizontal\" (the default). Full-width block line."}, {"cls": "origam-divider--vertical", "descriptionKey": "components.divider.anatomy.vertical", "descriptionFallback": "Applied when direction=\"vertical\". Inline-flex stretch line."}, {"cls": "origam-divider--inset", "descriptionKey": "components.divider.anatomy.inset", "descriptionFallback": "Applied when inset=true. Adds a leading margin offset."}], "svgDesc": "Schematic of the Divider component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamDivider", "rootClass": "origam-divider", "figcaption": "Anatomy of <code>&lt;origam-divider&gt;</code>. Horizontal ① is full-width; vertical ② is inline-flex with height: auto. Both render as a native <code>&lt;hr&gt;</code>.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-divider---opacity", "defaultValue": "0.12", "descriptionKey": "components.divider.css_vars.opacity", "descriptionFallback": "Global opacity of the divider line. Token: {opacity.100} resolves to 1; the component overrides to 0.12 by default in SCSS."}, {"name": "--origam-divider---border-top-width", "defaultValue": "thin", "descriptionKey": "components.divider.css_vars.border_top_width", "descriptionFallback": "Stroke thickness for the horizontal divider. Overridden by the thickness prop."}, {"name": "--origam-divider---border-right-width", "defaultValue": "thin", "descriptionKey": "components.divider.css_vars.border_right_width", "descriptionFallback": "Stroke thickness for the vertical divider. Overridden by the thickness prop."}, {"name": "--origam-divider---max-width", "defaultValue": "100%", "descriptionKey": "components.divider.css_vars.max_width", "descriptionFallback": "Maximum width for horizontal dividers. Set by the length prop."}, {"name": "--origam-divider---max-height", "defaultValue": "100%", "descriptionKey": "components.divider.css_vars.max_height", "descriptionFallback": "Maximum height for vertical dividers. Set by the length prop."}, {"name": "--origam-divider--inset---margin-inline-start", "defaultValue": "16px", "descriptionKey": "components.divider.css_vars.inset_margin", "descriptionFallback": "Leading indent applied when inset=true."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.divider.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.divider.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed dividerStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.divider.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.divider.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.divider.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.divider.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.divider.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.divider.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "inset", "labelKey": "components.divider.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "number", "prop": "thickness", "labelKey": "components.divider.playground.thickness", "defaultValue": 1, "labelFallback": "Thickness (px)"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('59b4d8b5-739e-4baf-9f89-4a93fe62795a', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'drawer', 'Drawer', 'Layout & Structure', NULL, 'mdi-page-layout-sidebar-left', 'components.catalog.drawer.description', 'Side-panel navigation drawer that integrates with the Origam layout grid. Supports rail/mini mode, expand-on-hover, temporary/persistent variants, touch drag, and four docking edges (left, right, top, bottom).', NULL, NULL, 'origam-drawer', NULL, 'packages/ds/src/components/Drawer/OrigamDrawer.vue', 'origam', NULL, NULL, '/stories/?story=components-drawer--design', '/docs/components/Drawer/OrigamDrawer.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.drawer.a11y.nav_note", "noteFallback": "The root element renders as <nav> by default (configurable via the tag prop). This gives it an implicit navigation landmark role, discoverable by screen reader landmark navigation."}, {"noteKey": "components.drawer.a11y.label_note", "noteFallback": "The root element carries aria-label set to the name prop (or \"Navigation\" as fallback). Provide a meaningful name prop when multiple navigation landmarks exist on the page."}, {"noteKey": "components.drawer.a11y.scrim_note", "noteFallback": "The scrim overlay in temporary mode is purely decorative and hidden from assistive technologies. It only handles click events to close the drawer."}], "roles": ["navigation"], "keyboard": [{"key": "Tab / Shift+Tab", "actionKey": "components.drawer.a11y.key_tab", "actionFallback": "Moves focus between interactive elements inside the drawer."}, {"key": "Escape", "actionKey": "components.drawer.a11y.key_escape", "actionFallback": "Closes the drawer when in temporary mode (if the overlay scrim is active)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-drawer---background", "descriptionKey": "components.drawer.tokens.background", "descriptionFallback": "Drawer surface background color."}, {"type": "shadow", "value": "var(--origam-shadow---none)", "tokenPath": "--origam-drawer---box-shadow", "descriptionKey": "components.drawer.tokens.box_shadow", "descriptionFallback": "Default shadow (none for permanent). Overridden to shadow.lg in temporary mode."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-drawer---transition-duration", "descriptionKey": "components.drawer.tokens.transition_duration", "descriptionFallback": "Open/close animation duration."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-drawer__temporary---box-shadow", "descriptionKey": "components.drawer.tokens.temporary_box_shadow", "descriptionFallback": "Shadow applied when the drawer is in temporary mode to elevate it above the scrim."}, {"type": "color", "value": "var(--origam-color__overlay---scrim)", "tokenPath": "--origam-drawer__scrim---background", "descriptionKey": "components.drawer.tokens.scrim_background", "descriptionFallback": "Background of the scrim shown behind the temporary drawer."}, {"type": "number", "value": "0.2", "tokenPath": "--origam-drawer__scrim---opacity", "descriptionKey": "components.drawer.tokens.scrim_opacity", "descriptionFallback": "Scrim opacity in temporary mode. Tracks drag progress during touch open/close."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- drawer panel -->\n  <rect x=\"30\" y=\"20\" width=\"200\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- prepend zone -->\n  <rect x=\"30\" y=\"20\" width=\"200\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.07))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"130\" y=\"54\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#prepend</text>\n  <!-- content zone -->\n  <rect x=\"30\" y=\"80\" width=\"200\" height=\"140\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"130\" y=\"155\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default (scrollable)</text>\n  <!-- append zone -->\n  <rect x=\"30\" y=\"220\" width=\"200\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"130\" y=\"254\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#append</text>\n  <!-- layout reservation hint -->\n  <rect x=\"240\" y=\"20\" width=\"440\" height=\"260\" rx=\"4\" fill=\"rgba(0,0,0,0.02)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"6 4\"/>\n  <text x=\"460\" y=\"155\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-style=\"italic\">layout main content (offset by drawer width)</text>\n  <!-- numbering -->\n  <circle cx=\"38\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"88\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"38\" y=\"92.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"38\" cy=\"228\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"232.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"38\" cy=\"148\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <!-- scrim overlay hint -->\n  <rect x=\"240\" y=\"20\" width=\"440\" height=\"260\" rx=\"4\" fill=\"rgba(0,0,0,0.06)\" stroke=\"rgba(0,0,0,0.1)\" stroke-width=\"1\" stroke-dasharray=\"3 3\" opacity=\"0.5\"/>\n  <text x=\"460\" y=\"40\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">scrim (temporary mode only)</text>\n", "code": "<teleport :to=\"layoutTarget\" :disabled=\"isLayoutOrphan\">\n  <origam-transition :transition=\"transition\">\n    <!-- root: nav by default -->\n    <nav v-if=\"isActive\" class=\"origam-drawer origam-drawer--left\">\n      <!-- inner wrapper: prepend | content | append -->\n      <div class=\"origam-drawer__wrapper\">\n        <!-- fixed header slot -->\n        <div class=\"origam-drawer__prepend\">\n          <slot name=\"prepend\" />\n        </div>\n\n        <!-- scrollable navigation content -->\n        <div class=\"origam-drawer__content\">\n          <slot name=\"default\" />\n        </div>\n\n        <!-- fixed footer slot -->\n        <div class=\"origam-drawer__append\">\n          <slot name=\"append\" />\n        </div>\n      </div>\n    </nav>\n  </origam-transition>\n\n  <!-- scrim: visible only in temporary mode -->\n  <origam-overlay-scrim :active=\"isTemporary && isActive\" @click=\"close\" />\n</teleport>", "legend": [{"cls": ".origam-drawer", "num": 1, "descriptionKey": "components.drawer.anatomy.root", "descriptionFallback": "Root nav element. Teleported into <code>#layout-id .origam-layout__wrapper</code> so it participates in the layout grid. Renders inline when no OrigamLayout ancestor exists."}, {"cls": ".origam-drawer__prepend", "num": 2, "descriptionKey": "components.drawer.anatomy.prepend", "descriptionFallback": "Fixed zone above the scrollable content. Rendered only when the #prepend slot is filled. <code>flex: none</code> so it does not participate in content scrolling."}, {"cls": ".origam-drawer__append", "num": 3, "descriptionKey": "components.drawer.anatomy.append", "descriptionFallback": "Fixed zone below the scrollable content. Rendered only when the #append slot is filled. <code>flex: none</code>."}, {"cls": ".origam-drawer__content", "num": 4, "descriptionKey": "components.drawer.anatomy.content", "descriptionFallback": "Scrollable content area hosting the #default slot. <code>overflow-y: auto</code>; fills remaining height between prepend and append."}], "classes": [{"cls": "origam-drawer", "descriptionKey": "components.drawer.anatomy.root", "descriptionFallback": "Root element. Controls all layout, transition, and z-index properties."}, {"cls": "origam-drawer--left", "descriptionKey": "components.drawer.anatomy.left", "descriptionFallback": "Applied when location=\"left\". Sets top: 0; left: 0 and right: auto, with border-right-width: thin."}, {"cls": "origam-drawer--right", "descriptionKey": "components.drawer.anatomy.right", "descriptionFallback": "Applied when location=\"right\". Sets top: 0; left: auto; right: 0, with border-left-width: thin."}, {"cls": "origam-drawer--temporary", "descriptionKey": "components.drawer.anatomy.temporary", "descriptionFallback": "Applied when temporary=true. Applies shadow.lg and shows the scrim."}, {"cls": "origam-drawer--rail", "descriptionKey": "components.drawer.anatomy.rail", "descriptionFallback": "Applied when rail=true. Collapses width to railWidth (default 56px)."}, {"cls": "origam-drawer--expand-on-hover", "descriptionKey": "components.drawer.anatomy.expand_on_hover", "descriptionFallback": "Applied when expandOnHover=true. Enables the hover-triggered width transition."}, {"cls": "origam-drawer--floating", "descriptionKey": "components.drawer.anatomy.floating", "descriptionFallback": "Applied when floating=true. Removes the side border."}, {"cls": "origam-drawer--sticky", "descriptionKey": "components.drawer.anatomy.sticky", "descriptionFallback": "Applied when sticky=true. Switches height to auto and uses position: sticky."}, {"cls": "origam-drawer__wrapper", "descriptionKey": "components.drawer.anatomy.wrapper", "descriptionFallback": "Inner flex container. Hosts prepend, content, and append zones in a column layout."}, {"cls": "origam-drawer__content", "descriptionKey": "components.drawer.anatomy.content", "descriptionFallback": "Scrollable main area. overflow-y: auto; flex: 0 1 auto; height: 100%."}, {"cls": "origam-drawer__prepend", "descriptionKey": "components.drawer.anatomy.prepend", "descriptionFallback": "Fixed header area. flex: none."}, {"cls": "origam-drawer__append", "descriptionKey": "components.drawer.anatomy.append", "descriptionFallback": "Fixed footer area. flex: none."}], "svgDesc": "Schematic of the Drawer component showing the three-zone layout: prepend, content, append.", "svgTitle": "Anatomy of OrigamDrawer", "rootClass": "origam-drawer", "figcaption": "Anatomy of <code>&lt;origam-drawer&gt;</code> — 4 parts: ① root drawer panel (teleported into the layout grid), ② prepend zone (fixed header), ③ append zone (fixed footer), ④ scrollable content (#default slot).", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-drawer---background", "defaultValue": "{color.surface.default}", "descriptionKey": "components.drawer.css_vars.background", "descriptionFallback": "Background color of the drawer panel."}, {"name": "--origam-drawer---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.drawer.css_vars.color", "descriptionFallback": "Foreground (text/icon) color."}, {"name": "--origam-drawer---box-shadow", "defaultValue": "{shadow.none}", "descriptionKey": "components.drawer.css_vars.box_shadow", "descriptionFallback": "Box shadow. Applied to shadow.lg automatically in temporary mode."}, {"name": "--origam-drawer---width", "defaultValue": "100%", "descriptionKey": "components.drawer.css_vars.width", "descriptionFallback": "Drawer panel width. Driven by the width prop and layout item styles (useLayoutItem)."}, {"name": "--origam-drawer---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.drawer.css_vars.transition_duration", "descriptionFallback": "Duration of the open/close slide animation."}, {"name": "--origam-drawer---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.drawer.css_vars.transition_timing_function", "descriptionFallback": "Easing function for the open/close transition."}, {"name": "--origam-drawer__scrim---background", "defaultValue": "{color.overlay.scrim}", "descriptionKey": "components.drawer.css_vars.scrim_background", "descriptionFallback": "Scrim overlay background color (temporary mode)."}, {"name": "--origam-drawer__scrim---opacity", "defaultValue": "0.2", "descriptionKey": "components.drawer.css_vars.scrim_opacity", "descriptionFallback": "Scrim opacity. Animates with drag progress during touch drag."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.drawer.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.drawer.exposed.css", "descriptionFallback": "Reactive CSS string from drawerStyles. Used by OrigamDefaultsProvider."}, {"name": "id", "type": "string", "descriptionKey": "components.drawer.exposed.id", "descriptionFallback": "Unique style-sheet ID for this drawer instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.drawer.exposed.load", "descriptionFallback": "Injects the computed style sheet on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.drawer.exposed.unload", "descriptionFallback": "Removes the injected style sheet on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.drawer.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "left", "value": "left"}, {"label": "right", "value": "right"}, {"label": "top", "value": "top"}, {"label": "bottom", "value": "bottom"}], "labelKey": "components.drawer.playground.location", "defaultValue": "left", "labelFallback": "Location"}, {"kind": "switch", "prop": "temporary", "labelKey": "components.drawer.playground.temporary", "defaultValue": false, "labelFallback": "Temporary"}, {"kind": "switch", "prop": "rail", "labelKey": "components.drawer.playground.rail", "defaultValue": false, "labelFallback": "Rail mode"}, {"kind": "switch", "prop": "expandOnHover", "labelKey": "components.drawer.playground.expand_on_hover", "defaultValue": false, "labelFallback": "Expand on hover"}, {"kind": "switch", "prop": "floating", "labelKey": "components.drawer.playground.floating", "defaultValue": false, "labelFallback": "Floating (no border)"}], "defaultSlotContent": "Navigation content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bdbb6d00-10d0-4a13-8296-a443373167cd', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'empty-state', 'EmptyState', 'Feedback & Status', NULL, 'mdi-inbox-outline', 'components.catalog.empty_state.description', 'Placeholder shown when a list, table or collection has nothing to display. Five visual presets (no-data, no-results, error, offline, locked) bundle icon + intent; both are overridable via props or slots.', NULL, NULL, 'origam-empty-state', NULL, 'packages/ds/src/components/EmptyState/OrigamEmptyState.vue', 'origam', NULL, NULL, '/stories/?story=components-emptystate--design', '/docs/components/EmptyState/OrigamEmptyState.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.empty_state.a11y.live_region", "noteFallback": "The root has role=\"status\" and aria-live=\"polite\". Screen readers announce the state change when the component appears or when preset changes without a page reload."}, {"noteKey": "components.empty_state.a11y.icon_hidden", "noteFallback": "The icon container carries aria-hidden=\"true\" — it is decorative. The meaningful information is in the title and description text nodes."}, {"noteKey": "components.empty_state.a11y.actions", "noteFallback": "Actions inside the #actions slot must individually carry correct roles (button, link). EmptyState does not wrap or intercept keyboard events."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---10)", "tokenPath": "--origam-empty-state---padding-block-md", "descriptionKey": "components.empty_state.tokens.padd