rigam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"160\" y=\"108\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"100\" cy=\"140\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"100\" y=\"144\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"250\" cy=\"176\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"250\" y=\"180\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<!-- root: role=\"status\" aria-live=\"polite\" -->\n<div class=\"origam-empty-state origam-empty-state--size-md origam-empty-state--align-center\">\n\n  <!-- icon area — aria-hidden -->\n  <div class=\"origam-empty-state__icon\" aria-hidden=\"true\">\n    <slot name=\"icon\">\n      <origam-icon class=\"origam-empty-state__icon-glyph\" />\n    </slot>\n  </div>\n\n  <!-- title — v-if=\"hasTitle\" -->\n  <div class=\"origam-empty-state__title\">\n    <slot name=\"title\">{{ title }}</slot>\n  </div>\n\n  <!-- description — v-if=\"hasDescription\" -->\n  <div class=\"origam-empty-state__description\">\n    <slot name=\"description\">{{ description }}</slot>\n  </div>\n\n  <!-- actions — v-if=\"hasActions\" -->\n  <div class=\"origam-empty-state__actions\">\n    <slot name=\"actions\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-empty-state", "num": 1, "descriptionKey": "components.empty_state.anatomy.root", "descriptionFallback": "Root element. Has role=\"status\" aria-live=\"polite\". Flex column. Width 100%."}, {"cls": ".origam-empty-state__icon", "num": 2, "descriptionKey": "components.empty_state.anatomy.icon", "descriptionFallback": "Icon container. aria-hidden=\"true\". Contains OrigamIcon or the #icon slot."}, {"cls": ".origam-empty-state__title", "num": 3, "descriptionKey": "components.empty_state.anatomy.title", "descriptionFallback": "Title element. Rendered when the title prop or the #title slot is present."}, {"cls": ".origam-empty-state__description", "num": 4, "descriptionKey": "components.empty_state.anatomy.description", "descriptionFallback": "Description element. Width clamped by --origam-empty-state---max-width (480px default). Rendered when description prop or #description slot is present."}, {"cls": ".origam-empty-state__actions", "num": 5, "descriptionKey": "components.empty_state.anatomy.actions", "descriptionFallback": "Actions row. Inline-flex with wrap. Rendered only when the #actions slot is provided."}], "classes": [{"cls": "origam-empty-state", "descriptionKey": "components.empty_state.anatomy.root", "descriptionFallback": "Root element. role=\"status\" aria-live=\"polite\". Flex column layout."}, {"cls": "origam-empty-state__icon", "descriptionKey": "components.empty_state.anatomy.icon", "descriptionFallback": "Icon wrapper with aria-hidden=\"true\". Centres the icon glyph."}, {"cls": "origam-empty-state__icon-glyph", "descriptionKey": "components.empty_state.anatomy.icon_glyph", "descriptionFallback": "OrigamIcon instance inside the icon wrapper. Inherits size and colour from CSS vars."}, {"cls": "origam-empty-state__title", "descriptionKey": "components.empty_state.anatomy.title", "descriptionFallback": "Title text element."}, {"cls": "origam-empty-state__description", "descriptionKey": "components.empty_state.anatomy.description", "descriptionFallback": "Description text element. max-width clamped by token."}, {"cls": "origam-empty-state__actions", "descriptionKey": "components.empty_state.anatomy.actions", "descriptionFallback": "Inline-flex actions row with gap and top margin."}], "svgDesc": "Schematic of the EmptyState component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamEmptyState", "rootClass": "origam-empty-state", "figcaption": "Anatomy of <code>&lt;origam-empty-state&gt;</code> — 5 internal parts. The root ① carries <code>role=\"status\"</code> and <code>aria-live=\"polite\"</code>; each section is conditionally rendered.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-empty-state---padding-block", "defaultValue": "{space.10} (40px)", "descriptionKey": "components.empty_state.css_vars.padding_block", "descriptionFallback": "Block padding of the root element. Per-size variants override this value."}, {"name": "--origam-empty-state---padding-inline", "defaultValue": "{space.6} (24px)", "descriptionKey": "components.empty_state.css_vars.padding_inline", "descriptionFallback": "Inline padding of the root element."}, {"name": "--origam-empty-state---gap", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.empty_state.css_vars.gap", "descriptionFallback": "Flex gap between icon, title, description and actions. Per-size overrides apply."}, {"name": "--origam-empty-state---max-width", "defaultValue": "480px", "descriptionKey": "components.empty_state.css_vars.max_width", "descriptionFallback": "Maximum width of the description text for readable line length."}, {"name": "--origam-empty-state__icon---size", "defaultValue": "64px", "descriptionKey": "components.empty_state.css_vars.icon_size", "descriptionFallback": "Icon font-size / size. Overridden per size class (sm=48px, md=64px, lg=96px)."}, {"name": "--origam-empty-state__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.empty_state.css_vars.icon_color", "descriptionFallback": "Icon colour. Overridden per intent modifier class (e.g. --intent-danger maps to danger feedback colour)."}, {"name": "--origam-empty-state__title---font-size", "defaultValue": "{font.size.xl} (1.25rem)", "descriptionKey": "components.empty_state.css_vars.title_font_size", "descriptionFallback": "Title font size. Overridden per size class."}, {"name": "--origam-empty-state__description---font-size", "defaultValue": "{font.s