INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c78f45d3-d1f6-4d38-9f0b-ceeb1f76e196', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'number-field', 'NumberField', 'Form & Input', NULL, 'mdi-numeric', 'components.catalog.number_field.description', 'Numeric input field with built-in increment/decrement controls, min/max/step clamping, precision formatting, hold-to-repeat, split layout, and full form validation support.', NULL, NULL, 'origam-number-field', NULL, 'packages/ds/src/components/NumberField/OrigamNumberField.vue', 'origam', NULL, NULL, '/stories/?story=components-numberfield--design', '/docs/components/NumberField/OrigamNumberField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.number_field.a11y.group_note", "noteFallback": "The control container has role=\"group\" and aria-label matching the field label, grouping the input + buttons semantically."}, {"noteKey": "components.number_field.a11y.button_labels", "noteFallback": "Increment and decrement buttons have aria-label=\"Increment\" and aria-label=\"Decrement\" respectively. They also have aria-hidden=\"true\" on their icon children."}, {"noteKey": "components.number_field.a11y.disabled_note", "noteFallback": "When value reaches min or max, the corresponding button is disabled (pointer-events: none, aria-disabled=\"true\")."}], "roles": ["group", "spinbutton"], "keyboard": [{"key": "ArrowUp", "actionKey": "components.number_field.a11y.key_increment", "actionFallback": "Increments the value by step."}, {"key": "ArrowDown", "actionKey": "components.number_field.a11y.key_decrement", "actionFallback": "Decrements the value by step."}, {"key": "Tab", "actionKey": "components.number_field.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element (input → increment → decrement)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"20\" width=\"640\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"37\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">Quantity</text>\n  <rect x=\"60\" y=\"44\" width=\"480\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\"/>\n  <text x=\"80\" y=\"60\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #111)\" font-family=\"''JetBrains Mono'',monospace\">5</text>\n  <rect x=\"560\" y=\"24\" width=\"48\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--secondary---bgHover, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"584\" y=\"38\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #7c3aed)\" text-anchor=\"middle\">+</text>\n  <text x=\"584\" y=\"64\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #7c3aed)\" text-anchor=\"middle\">−</text>\n  <rect x=\"30\" y=\"90\" width=\"640\" height=\"26\" rx=\"3\" fill=\"transparent\"/>\n  <text x=\"60\" y=\"107\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — hint text</text>\n  <circle cx=\"26\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"26\" cy=\"90\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"94\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"550\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"550\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"550\" cy=\"42\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"550\" y=\"46\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"550\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"550\" y=\"66\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"26\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<origam-field class=\"origam-number-field\">\n  <!-- outer prepend / append slots -->\n  <slot name=\"prepend\"/>\n\n  <!-- field composite: label + input + inner icons + controls -->\n  <slot name=\"field\">\n    <!-- label, prefix, input, suffix are managed by OrigamInput -->\n    <div class=\"origam-number-field__control\" role=\"group\" :aria-label=\"label\">\n      <!-- decrement (split-left or stacked-bottom) -->\n      <origam-btn aria-label=\"Decrement\" @click=\"decrement\" />\n\n      <!-- native <input type=\"number\"> -->\n      <input class=\"origam-number-field__compact-input\" :aria-label=\"label\" />\n\n      <!-- increment (split-right or stacked-top) -->\n      <origam-btn aria-label=\"Increment\" @click=\"increment\" />\n    </div>\n  </slot>\n\n  <slot name=\"append\"/>\n\n  <!-- details: messages + counter -->\n  <slot name=\"details\">\n    <origam-messages :messages=\"errorMessages\" />\n  </slot>\n</origam-field>", "legend": [{"cls": ".origam-number-field", "num": 1, "descriptionKey": "components.number_field.anatomy.root", "descriptionFallback": "Root OrigamField container. Holds the label, input area, and details zone."}, {"cls": ".origam-messages (details slot)", "num": 2, "descriptionKey": "components.number_field.anatomy.messages", "descriptionFallback": "Details zone below the field — renders hint, error messages, and counter."}, {"cls": ".origam-number-field__control", "num": 3, "descriptionKey": "components.number_field.anatomy.control", "descriptionFallback": "Wrapper for the stacked or split increment/decrement buttons."}, {"cls": ".origam-number-field__compact-input", "num": 4, "descriptionKey": "components.number_field.anatomy.compact_input", "descriptionFallback": "Compact-mode inner input shown between the stacked controls."}, {"cls": "increment button", "num": 5, "descriptionKey": "components.number_field.anatomy.increment", "descriptionFallback": "Increment (+) button. aria-label=\"Increment\". Disabled when value >= max."}, {"cls": "decrement button", "num": 6, "descriptionKey": "components.number_field.anatomy.decrement", "descriptionFallback": "Decrement (−) button. aria-label=\"Decrement\". Disabled when value <= min."}], "classes": [{"cls": "origam-number-field", "descriptionKey": "components.number_field.anatomy.root", "descriptionFallback": "Root field container."}, {"cls": "origam-number-field__control", "descriptionKey": "components.number_field.anatomy.control", "descriptionFallback": "Wrapper for the increment/decrement controls (role=\"group\")."}, {"cls": "origam-number-field__compact-input", "descriptionKey": "components.number_field.anatomy.compact_input", "descriptionFallback": "Input element shown between stacked controls in compact mode."}], "svgDesc": "Schematic of the NumberField component with 6 numbered parts.", "svgTitle": "Anatomy of OrigamNumberField", "rootClass": "origam-number-field", "figcaption": "Anatomy of <code>&lt;origam-number-field&gt;</code> — 6 parts: root field, input area, control container, increment button, decrement button, and messages/details row.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-number-field---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.number_field.css_vars.background_color", "descriptionFallback": "Field background color."}, {"name": "--origam-number-field---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.number_field.css_vars.color", "descriptionFallback": "Field text color."}, {"name": "--origam-number-field---border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.number_field.css_vars.border_color", "descriptionFallback": "Default border color. Overridden to focus / error variants on interaction."}, {"name": "--origam-number-field---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.number_field.css_vars.border_radius", "descriptionFallback": "Border-radius of the field container."}, {"name": "--origam-number-field---opacity-disabled", "defaultValue": "{opacity.50}", "descriptionKey": "components.number_field.css_vars.opacity_disabled", "descriptionFallback": "Opacity applied when disabled=true."}, {"name": "--origam-number-field__increment---background-color-hover", "defaultValue": "{color.action.secondary.bgHover}", "descriptionKey": "components.number_field.css_vars.increment_bg_hover", "descriptionFallback": "Background of the increment button on hover."}, {"name": "--origam-number-field__decrement---background-color-hover", "defaultValue": "{color.action.secondary.bgHover}", "descriptionKey": "components.number_field.css_vars.decrement_bg_hover", "descriptionFallback": "Background of the decrement button on hover."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.number_field.playground.model_value", "defaultValue": 5, "labelFallback": "Value"}, {"kind": "number", "prop": "min", "labelKey": "components.number_field.playground.min", "defaultValue": 0, "labelFallback": "Min"}, {"kind": "number", "prop": "max", "labelKey": "components.number_field.playground.max", "defaultValue": 100, "labelFallback": "Max"}, {"kind": "number", "prop": "step", "labelKey": "components.number_field.playground.step", "defaultValue": 1, "labelFallback": "Step"}, {"kind": "switch", "prop": "split", "labelKey": "components.number_field.playground.split", "defaultValue": false, "labelFallback": "Split layout"}, {"kind": "switch", "prop": "compact", "labelKey": "components.number_field.playground.compact", "defaultValue": false, "labelFallback": "Compact"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.number_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "underlined", "value": "underlined"}, {"label": "solo", "value": "solo"}, {"label": "plain", "value": "plain"}], "labelKey": "components.number_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}]}, "previewVariants": [{"label": "default", "props": {"max": 100, "min": 0, "label": "Quantity", "modelValue": 5}}, {"label": "split", "props": {"label": "Price", "split": true, "modelValue": 19}}, {"label": "compact", "props": {"max": 99, "min": 1, "label": "Count", "compact": true, "modelValue": 3}}, {"label": "disabled", "props": {"label": "Disabled", "disabled": true, "modelValue": 10}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
