INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('91cc03ed-907c-499d-99fb-81748e9e643e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'component', 'slide-x', 'SlideX', 'Utilities & Providers', NULL, 'mdi-arrow-left-right', 'components.catalog.transition_slide_x.description', 'CSS-driven Vue transition that slides a child element horizontally (translateX −15px → identity) combined with an opacity fade. Sub-component of the Transition family.', NULL, NULL, 'origam-slide-x', NULL, 'packages/ds/src/components/Transition/OrigamSlideX.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', 'transition', '{"a11y": {"notes": [{"noteKey": "components.slide_x.a11y.reduced_motion", "noteFallback": "Animation is disabled automatically when prefers-reduced-motion: reduce is detected (disabled=true via useCssTransition)."}, {"noteKey": "components.slide_x.a11y.no_role", "noteFallback": "The wrapper is transparent to the accessibility tree. Only the slotted child is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"170\" y=\"83\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <text x=\"170\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">translateX(−15px) → 0</text>\n  <text x=\"170\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 0 → 1</text>\n  <rect x=\"400\" y=\"40\" width=\"260\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"530\" y=\"83\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <text x=\"530\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">0 → translateX(−15px)</text>\n  <text x=\"530\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">opacity: 1 → 0</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"95\" font-size=\"22\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- wraps <transition> or <transition-group> via useCssTransition -->\n<component :is=\"tag\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>\n\n<!-- CSS (global, not scoped) -->\n<!-- .origam-transition--slide-x-enter-from,\n     .origam-transition--slide-x-leave-to { opacity: 0; transform: translateX(-15px); }\n     .origam-transition--slide-x-enter-active,\n     .origam-transition--slide-x-leave-active { transition-property: transform, opacity; transition-duration: 0.3s; } -->", "legend": [{"cls": ".origam-transition--slide-x-enter-active", "num": 1, "descriptionKey": "components.slide_x.anatomy.enter", "descriptionFallback": "Enter phase. Child animates from translateX(−15px) + opacity:0 to identity. Duration: 0.3 s, easing: cubic-bezier(0.4,0,0.2,1)."}, {"cls": ".origam-transition--slide-x-leave-active", "num": 2, "descriptionKey": "components.slide_x.anatomy.leave", "descriptionFallback": "Leave phase. Child slides back to translateX(−15px) + opacity:0 over 0.3 s."}], "classes": [{"cls": "origam-transition--slide-x", "descriptionKey": "components.slide_x.anatomy.class_root", "descriptionFallback": "CSS transition class prefix applied by Vue."}, {"cls": "origam-transition--slide-x-enter-from", "descriptionKey": "components.slide_x.anatomy.class_enter_from", "descriptionFallback": "Starting state: opacity:0, transform: translateX(−15px)."}, {"cls": "origam-transition--slide-x-leave-to", "descriptionKey": "components.slide_x.anatomy.class_leave_to", "descriptionFallback": "End state on leave: same as enter-from (symmetric)."}, {"cls": "origam-transition--slide-x-enter-active", "descriptionKey": "components.slide_x.anatomy.class_enter_active", "descriptionFallback": "Active enter: transitions transform and opacity over 0.3 s."}, {"cls": "origam-transition--slide-x-leave-active", "descriptionKey": "components.slide_x.anatomy.class_leave_active", "descriptionFallback": "Active leave: transitions transform and opacity over 0.3 s."}, {"cls": "origam-transition--slide-x-move", "descriptionKey": "components.slide_x.anatomy.class_move", "descriptionFallback": "Move transition in group mode: transform only, 0.5 s."}], "svgDesc": "Schematic of the slide-x transition with enter and leave phases.", "svgTitle": "Anatomy of OrigamSlideX", "rootClass": "origam-transition--slide-x", "figcaption": "Anatomy of <code>&lt;origam-slide-x&gt;</code> — enter ① slides from translateX(−15px) + opacity:0 to identity. Leave ② reverses the same transform + fades out. Duration: 0.3 s; move: 0.5 s.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-transition---slide-x-distance", "defaultValue": "100%", "descriptionKey": "components.slide_x.css_vars.distance", "descriptionFallback": "Horizontal translate distance token. The component hardcodes −15px in its CSS class; this token is the declared reference value."}, {"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.slide_x.css_vars.duration", "descriptionFallback": "Default transition duration (0.3 s hardcoded in CSS class)."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.decelerate}", "descriptionKey": "components.slide_x.css_vars.easing", "descriptionFallback": "Easing function for slide-x (decelerate: cubic-bezier(0.4,0,0.2,1))."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.slide_x.exposed.filter_props", "descriptionFallback": "Forwards a filtered subset of props to the underlying transition."}], "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "(none)", "value": ""}, {"label": "in-out", "value": "in-out"}, {"label": "out-in", "value": "out-in"}], "labelKey": "components.slide_x.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.slide_x.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "group", "labelKey": "components.slide_x.playground.group", "defaultValue": false, "labelFallback": "Group mode"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
