INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3f7655c1-3d56-4572-b6c0-2d261db254c8', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'const', 'block-array', 'BLOCK_ARRAY', 'Layout & Sizing', NULL, NULL, 'consts.catalog.block_array.description', 'Array of the two block-axis anchor values (top and bottom). Used by the anchor / positioning system to enumerate vertical placement options without including inline or start/end variants.', 'export const BLOCK_ARRAY: Array<TBlock> = [BLOCK.TOP, BLOCK.BOTTOM]', NULL, NULL, NULL, 'packages/ds/src/consts/Commons/anchor.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
