INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f23f2768-d6f7-4b7a-9a3f-117a7003edfe', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'composable', 'use-props', 'useProps', NULL, 'Commons', 'mdi-tune-variant', '', 'Returns a filterProps utility that picks only the keys declared on a component interface from an arbitrary props object, stripping undefined values so that Vue 3 boolean-prop coercion does not silently override withDefaults in child components. Used by composite components (DataTable, List, Select…) to forward a safe subset of their own props to child Origam components.', NULL, 'function useProps<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7f719908-3443-49bd-8e81-a9eb22e937b8', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'composable', 'use-qr-code', 'useQrCode', NULL, 'QrCode', 'mdi-qrcode', '', 'Headless QR-code composable. Encodes a string payload using qrcode-generator (Reed-Solomon + matrix masking) and returns a reactive SVG string, the raw module matrix, and the matrix size. The encoder is LRU-cached at module level to avoid rebuilding identical matrices on re-renders. Fully SSR-safe — no DOM API is touched.', NULL, 'function useQrCode(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3baf67eb-d8d5-4774-81e0-0da06c703e3e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'composable', 'use-refs', 'useRefs', NULL, 'Commons', 'mdi-link-variant', '', 'Manages a dynamic array of template refs that is reset before each update cycle. Provides an updateRef(el, i) callback designed for use with :ref in v-for loops, where Vue replaces individual refs by index. The refs array is always fresh (cleared in onBeforeUpdate) so stale elements from a previous render do not leak.', NULL, 'function useRefs<T extends object>(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('7c3d242e-8882-4357-9695-08eb68f90451', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'composable', 'use-resize-observer', 'useResizeObserver', NULL, 'Commons', 'mdi-resize', '', 'Wraps the native ResizeObserver API with a reactive template ref. Returns a resizeRef to attach to any element and a readonly contentRect that updates on every resize. Automatically disconnects the observer on component unmount. Supports both content-box (default) and border-box measurement.', NULL, 'function useResizeObserver(
