INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('11c3f648-e0c6-4bca-a16c-ec3555ee335e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'interface', 'i-media-controller-emits', 'IMediaControllerEmits', 'Events & Emits', NULL, NULL, 'interfaces.catalog.i_media_controller_emits.description', 'Emits surfaced by <OrigamMediaController>. The shell calls methods.* directly for the basic ops (toggle play, seek, set volume, set rate, toggle mute, request cast) — those do not bubble. These emits are the ones the parent must handle because the Controller does not own enough context.', 'export interface IMediaControllerEmits {
    (e: ''quality-change'', quality: string): void
    (e: ''download''): void
    (e: ''previous''): void
    (e: ''next''): void
    (e: ''update:loopMode'', mode: TAudioLoopMode): void
    (e: ''update:shuffle'', shuffle: boolean): void
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('35e56e72-c719-4cad-9e19-49746db92324', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'interface', 'i-media-controller-props', 'IMediaControllerProps', 'Component Props', NULL, NULL, 'interfaces.catalog.i_media_controller_props.description', 'Props for <OrigamMediaController> — the universal media-controls shell consumed by <OrigamVideo> and <OrigamAudio>. Purely presentational: it receives state and methods from the parent and emits intents back. Audio-specific controls (loop, shuffle, prev/next) are opt-in so video consumers see zero regression.', 'export interface IMediaControllerProps extends ICommonsComponentProps {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dcb0c361-a113-4bec-ab5b-f1b0d1cf6df0', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'interface', 'i-media-controller-slots', 'IMediaControllerSlots', 'Slots', NULL, NULL, 'interfaces.catalog.i_media_controller_slots.description', 'Scoped slots exposed by <OrigamMediaController>. Consumers inject media-specific blocks: OrigamAudio injects header + waveform + footer; OrigamVideo injects captions/PiP/fullscreen through extraControlsRight.', 'export interface IMediaControllerSlots {
