INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c2822a14-1943-490a-9075-103bdb103652', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'dbb26ed3-3d86-4862-bb7f-a6658c5d05e4', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('971cdbc9-51d2-4e62-9eb4-48e9be134665', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'dbb26ed3-3d86-4862-bb7f-a6658c5d05e4', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f01d0335-2a21-4496-9865-914feeb31cf5', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'dbb26ed3-3d86-4862-bb7f-a6658c5d05e4', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e24e74c3-349b-4712-96ba-f9670826fe26', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'fdb72d1b-c0cd-4f28-84ed-fcd4e2d3a52e', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f9ae14bd-1340-4f55-b3bf-51a7e5e672f2', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'fdb72d1b-c0cd-4f28-84ed-fcd4e2d3a52e', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f7429d6-927b-44a2-a8bb-8f5e261fac76', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'fdb72d1b-c0cd-4f28-84ed-fcd4e2d3a52e', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6bf658b6-9328-4b6a-b1bc-1c8d84d2cf2e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '11f43d2d-6e88-40cb-93d6-029f8d32458e', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7beab3f-b3d1-4494-a8bc-85e7b67d51f9', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '11f43d2d-6e88-40cb-93d6-029f8d32458e', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('32a6932d-6236-4d81-98c8-4be88681e0b6', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '11f43d2d-6e88-40cb-93d6-029f8d32458e', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
