INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59e0f441-857e-4526-ade8-011b5754265c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1f03de5c-6d68-4566-8d30-6d65f2dec80f', 'link', 'IUseLink', true, NULL, '', 'The link object returned by useRouter/useLink. Exposes isLink (whether an href/to prop is present) and isActive (whether the current route matches the link target). Watched by the composable to trigger selection.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e5c58b85-521a-4bb8-8ad8-257d6e0a4e1d', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1f03de5c-6d68-4566-8d30-6d65f2dec80f', 'select', '(value: boolean, e?: Event) => void', false, NULL, '', 'The group selection callback injected by useGroup. When the link becomes active, this is called with value=true on the next tick. When undefined, the composable becomes a no-op.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17f11b52-fbce-4c56-b0cd-e2f5cb727ee0', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'e7922bac-9265-455c-bcc7-b3075cf6a3a6', 'options', 'ISheetSwipeOptions', true, NULL, '', 'Configuration object. Includes el (sheet root element ref), handle (drag handle element ref), snapPoints (reactive array of TSheetSnapPoint), defaultSnap (initial snap id), disabled (Ref<boolean> to suspend gesture), and persistent (Ref<boolean> to block the closed snap).', 0, false, NULL, NULL);
