INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc6ec814-8b81-4990-a29c-6a3dd665c2bb', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '519d3340-2a62-4b08-b6cd-ab2c0083ba89', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f43bac0-682d-4b03-b090-77b8d972f78c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '5def3c9c-6800-414d-a75a-a7e99c932508', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('185de8d9-74d0-4865-bc7b-1c475c1082cf', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '33f60ed9-59d1-4a55-8043-325242a5a241', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
