INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da8a17b9-0c80-473b-8922-db36f19ba4cf', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ab34cc11-82ce-4a65-aab0-012f1113c16e', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8b8290bb-a034-48e4-9fdb-f95cc3231bc6', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ab34cc11-82ce-4a65-aab0-012f1113c16e', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('07ea3898-54e8-4949-b7b8-f2caa5469d84', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'f18398c3-3c85-4da1-9758-719b2f5257af', 'value', 'number', true, NULL, 'utils.detail.clamp.param_value', 'The number to constrain.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('354d60f8-7991-4dee-8385-344d8158485b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ab34cc11-82ce-4a65-aab0-012f1113c16e', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e81011c4-5441-468e-82fd-d1ca12db5eed', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f0d0ddf-bf4c-4ea0-b820-63141113b1c5', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('88b37b0d-471c-4eaf-abc4-97a8f55c521f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('70571309-5cd2-4f25-87e4-df26ba34ad1e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce3daa75-052b-4090-acae-2eb221f926c8', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('10060c2e-6ee0-44a4-b4b5-729569403bda', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4e337813-565c-43a0-92b1-e68d04c65b5c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c5314069-2689-4a08-aa44-be402911c5e1', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'fff0e466-39b7-41c4-a31d-a39c3e428adc', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
