INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d30c01d6-9337-4088-9a6c-9a349feccd26', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('03180e10-2556-4835-a297-f996578ea355', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('58e7b561-750d-4fb3-996e-d51a31972e45', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
