INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('403a9022-45d2-4642-9c79-aaeaae93c20a', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
