INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('33a05c51-7018-4605-b05a-ad5ea12aa47f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '9bbe7a9d-b6aa-49a2-b0cf-9e9457e1d76a', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('22bc0e9f-67e7-465d-b71d-6185495fa86f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'f9ecc86a-93cd-4304-8e73-5b7029cee073', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6b63dd34-abb6-4b56-8f83-248c2976aef1', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'f9ecc86a-93cd-4304-8e73-5b7029cee073', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bd59eaca-3b18-4cc0-90b0-876e5940df8a', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'e1140ec7-be45-4eca-b85a-177a581da3a1', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5b61ee7e-e4ad-47f2-b755-432a6725ad59', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'e1140ec7-be45-4eca-b85a-177a581da3a1', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('703380c1-026f-4b5f-a7cf-ff0e0b8ed0bd', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1d669e90-f10b-4ca1-8df2-c51617955c0d', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5dbdc0e1-02c8-4ade-ba8c-ac81676bfc02', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1d669e90-f10b-4ca1-8df2-c51617955c0d', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d3f5441-3e38-40e4-af3c-347d2f6a801c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1d669e90-f10b-4ca1-8df2-c51617955c0d', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a26e5254-aca6-4aa2-9690-3a7c9a85c576', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1d669e90-f10b-4ca1-8df2-c51617955c0d', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7dafbd8c-94b2-4482-9087-ddcbc7565c6b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '1d669e90-f10b-4ca1-8df2-c51617955c0d', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
