INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0509fa5a-9f5f-4dfb-9c35-298c3b78916b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87cd3306-7a26-4b7b-93c8-a207b3515b04', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ad3a4b20-8295-4695-9820-356474b3ddcd', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f853c809-8feb-40bd-a126-c89eab50b29c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ad3a4b20-8295-4695-9820-356474b3ddcd', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e04f9f5b-43da-461f-921b-05a9b40c94cc', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ad3a4b20-8295-4695-9820-356474b3ddcd', 'defaultValue', 'MaybeRefOrGetter<Props[Prop] | undefined>', false, NULL, '', 'Value used to initialise the internal ref when the prop is undefined on first render.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81a39e17-a5de-4144-9959-5e1f71a03afb', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ad3a4b20-8295-4695-9820-356474b3ddcd', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
