INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fafd9e55-004a-4ebb-bf8e-8f8252ae2044', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '7f505927-12a8-4822-867c-32c9cdb9da2b', 'options', 'MaybeRefOrGetter<IUseWatermarkOptions>', false, '{}', '', 'Options bag (static object, reactive ref, or getter function). Reads: `text`, `image` (URL), `opacity` (default 0.15), `angle` (degrees, default -30), `gap` (tile spacing in px, default 100), `fontSize` (px, default 16), `fontFamily`, `color`, `fontWeight`, `pointerEvents` ("none" | "auto"), `zIndex`, `antiTamper` (enable MutationObserver re-injection). Passing a ref makes patternUrl update reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2c2a66f7-9372-4e7c-899e-0b808f900a26', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a1072ae4-7d13-46d4-8e1c-d56e67100f52', 'srcRef', 'Ref<string | undefined | null>', true, NULL, '', 'Reactive reference to the audio file URL. The composable watches this ref and re-triggers computation whenever the value changes. null / undefined clears the peaks array.', 0, false, NULL, NULL);
