INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('493a63ba-f4a5-405a-a235-1ca9a531610f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:46.145598+00', '30518238-96ea-45ab-b708-d505c5660382', 'location', 'TAnchor', NULL, NULL, true, NULL, NULL, NULL, 'Side and alignment where the floating content appears relative to the activator (e.g. "bottom start", "top end").', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('09c8e053-1a26-4309-b907-4aa6e395c647', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:46.145598+00', '30518238-96ea-45ab-b708-d505c5660382', 'origin', 'TAnchor | ''auto'' | ''overlap''', NULL, NULL, true, NULL, NULL, NULL, 'The anchor point on the floating content itself. "auto" mirrors the location; "overlap" places the panel over the activator.', 2, false, NULL, NULL);
