INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3c4e3099-f240-44e1-ab21-e50495ab8f86', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:46.145598+00', '0e41488a-4993-4d9f-9534-f3f8df48a214', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
