INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1634474d-f3dd-45d6-a56b-63e54057fbe1', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '5def3c9c-6800-414d-a75a-a7e99c932508', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('43077b73-6194-41df-af25-b1035f8dc0b7', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '5def3c9c-6800-414d-a75a-a7e99c932508', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c0326a9a-d8ed-4dfe-b01f-5494424e72aa', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '5def3c9c-6800-414d-a75a-a7e99c932508', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f4782a58-ef60-4dbd-9df6-8c7cd7a456aa', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '33f60ed9-59d1-4a55-8043-325242a5a241', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('90a891b4-8cc2-454a-8228-35fc42689e64', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '33f60ed9-59d1-4a55-8043-325242a5a241', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5c0ca3b5-889c-4e91-8533-fe20fc05601c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '33f60ed9-59d1-4a55-8043-325242a5a241', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20a2f324-8006-4162-b1c1-846541c2a0c9', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '33f60ed9-59d1-4a55-8043-325242a5a241', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d28ecdd5-996d-47d9-aa7d-a8c0852945d3', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '8c04a8ba-8be6-4579-8ea4-b4c03e3744c1', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('557179bd-003b-435f-a8c6-ed500cc18467', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '8c04a8ba-8be6-4579-8ea4-b4c03e3744c1', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('470d1434-6806-4527-a543-161b84efae8c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '8c04a8ba-8be6-4579-8ea4-b4c03e3744c1', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a437238e-e665-4d76-b1e2-4e0e65935f8d', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '8c04a8ba-8be6-4579-8ea4-b4c03e3744c1', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('764695a3-af7e-4bd8-bd40-1c70892f3692', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2653ad9f-ae3b-4627-b3ec-7e0ea5cdf57e', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bba77d57-bfcb-4fa2-a47a-c096143e88ef', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2653ad9f-ae3b-4627-b3ec-7e0ea5cdf57e', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('995b6fd3-ad44-4e8f-9f48-35fcafdb5ee2', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2653ad9f-ae3b-4627-b3ec-7e0ea5cdf57e', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('54acaa7c-14cf-4925-94b5-a5821494b1b6', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '0fd8e5c3-0ff8-4524-bcfc-f05425d8d39d', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aa7ddc23-8908-4c47-8da5-9b2bdc36e43b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '0fd8e5c3-0ff8-4524-bcfc-f05425d8d39d', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8bcd5b79-6d94-427b-aa2c-d7781b27d79d', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a76cbd8c-708d-43c1-a28f-560ae665eaac', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b14e326e-0470-43e1-be55-9428bd646ce2', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ab34cc11-82ce-4a65-aab0-012f1113c16e', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d675e734-db80-4c5b-888b-d99a3d4f923c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ab34cc11-82ce-4a65-aab0-012f1113c16e', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e64a041e-8e37-4f63-bbcd-c2c601120708', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ab34cc11-82ce-4a65-aab0-012f1113c16e', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c26d8cc-17a9-4873-8230-bd2a19099cfa', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('59c0af50-10cc-4f43-b006-90efbcaffa7f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('537ecb83-7086-422a-b452-459dff4dcb0e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('742ad5a5-956c-4ef1-853e-fcba7be67c21', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('46a05076-6ee8-4363-8bcb-67993a770a33', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5c024ffa-f104-4de3-b398-5d6cd9ae72f3', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cfaf423b-5609-4bc6-804e-9a5fb179f21f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3a168488-a881-44bb-97e4-dfc49d84324a', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d977c4c8-1eae-4fb0-9a01-47420b4ead5a', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '99c39340-35de-4657-982c-2dc7137402d9', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f771df1-f406-4d88-a59a-d7d1047a01dd', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '99c39340-35de-4657-982c-2dc7137402d9', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0fad42ba-dd52-4f55-93e1-67d0522a3ff8', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '99c39340-35de-4657-982c-2dc7137402d9', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5710d2cc-8da5-44c6-a97e-c16a9b423835', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '99c39340-35de-4657-982c-2dc7137402d9', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5cdcdde5-21ab-44fc-b0e0-2cb97f7d4ae7', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '99c39340-35de-4657-982c-2dc7137402d9', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b05070be-38c7-429e-a01a-81b5aa11430b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '4490e4f0-3446-4810-b264-529b08565c13', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('331761d9-9709-4485-9a97-3c29ea5f4d4c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '4490e4f0-3446-4810-b264-529b08565c13', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fdda8ec6-e0d5-4843-bd00-30968d1c8eda', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2b2d1d0a-fcf6-4142-8d2a-7f77391375f7', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('47e2788d-7bff-40f8-8d45-065947c99787', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a8cfad8a-eca5-4ecd-a323-c59d1e25683d', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'b5dfce20-0184-46e3-b27e-b625009a247f', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b70cb5b7-2baf-45ca-bbc7-1e920a534e2d', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '84a4f063-f7c6-4325-9153-23f4372231db', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1cf44977-5db8-443c-adba-375f094007a5', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('43760a68-435b-4ea8-93ee-0f6690254609', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('90cc0ce1-f9e6-4d93-bc45-387f50b5dc97', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('42257ab5-a17e-456a-82c4-f38c5d5ac3a4', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('634b35cb-c73d-455a-aa88-cab97f74fbc8', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('abbbe53e-fda2-4d52-82df-d8ace8b10590', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '2002df85-6f7e-4fb7-acb2-0237ac87b18f', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('15dbd44d-8fba-4120-aad6-96ffa3684b6e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '9bbe7a9d-b6aa-49a2-b0cf-9e9457e1d76a', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8a27f338-8a84-4b2d-b72a-c840c6f2f35f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '9bbe7a9d-b6aa-49a2-b0cf-9e9457e1d76a', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('76f9fc3d-7568-419b-9a19-bcb1cc2fccb6', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '7d617bd3-0146-4aaa-90ac-ebaf3c61f63a', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
