INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb3abbe1-b43a-49c8-804b-f3d2eecb287e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '3474bc29-a47c-4b3d-be57-7dfea4d8fa3b', 'getVelocity', '(id: number) => { x: number; y: number; direction: string }', '', 'Compute the velocity vector for the given touch identifier from the recent sample history. Returns px/ms values for x and y axes and the dominant direction string. Throws if no samples are found for the id.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d307cad-a7d8-44e2-ba47-ac31ba922b66', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'f370af1d-00ab-4857-b2f5-3ef9eb4be983', 'videoRef', 'Ref<HTMLVideoElement | null>', '', 'Template ref to bind to the `<video>` element. Reused from `options.videoRef` when provided.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1b55a1ad-edcf-4fe7-8711-3954fe4e8a5b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'f370af1d-00ab-4857-b2f5-3ef9eb4be983', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('89338218-a8e7-4156-b357-998f489a9f7f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'f370af1d-00ab-4857-b2f5-3ef9eb4be983', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eba00e31-fe46-4f88-bf52-1e29c314d9f9', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('da6621a4-d4f3-49aa-b5d0-23ab4fb7365b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f0a47142-dcb4-4526-bc72-92c0114f584b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1399e391-6a0d-41f7-972c-26b02802e93e', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ea1ac2e6-797c-4e91-abdf-7ba9752fd8da', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f576a28d-10ba-4d89-8393-d71cf5197ca0', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b21c357-7e90-462d-beb8-566e357e554b', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('708d507d-eead-4354-b539-8046c4872dd3', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7ecc0a9-c1ab-4379-b59e-0d3c6a1a8483', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '30ab757d-887e-4fff-9fee-de984a77f82f', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('887d05be-1279-4510-8799-91521fea2c31', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'ad3a4b20-8295-4695-9820-356474b3ddcd', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9f6b0f64-b7ac-4520-bf8c-307ce8616ef0', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '7f505927-12a8-4822-867c-32c9cdb9da2b', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('95d9348a-877b-41c5-ae72-0ae8423e3503', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', '7f505927-12a8-4822-867c-32c9cdb9da2b', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
