INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cce7fa60-61e6-456f-9ac9-a72d06009fb1', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a1072ae4-7d13-46d4-8e1c-d56e67100f52', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
