INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1f3fda17-adaa-4b11-8688-609388684a48', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a1072ae4-7d13-46d4-8e1c-d56e67100f52', 'error', 'Ref<Error | null>', '', 'Captures fetch errors (non-2xx response), decode errors (corrupt / unsupported audio), and OfflineAudioContext unavailability. null when no error.', 2, false, NULL, NULL);
