INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ccb2fb3b-352b-4b13-bc96-56cd3beed77f', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'd1d5b11e-53d7-444f-912c-09ce44ff2e8e', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9dfbf5b8-7fd5-4700-9fa6-48764f883edb', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'd1d5b11e-53d7-444f-912c-09ce44ff2e8e', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a3cdc784-7753-47ff-9717-1cecedc492c4', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'd1d5b11e-53d7-444f-912c-09ce44ff2e8e', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a5409dbf-0d7b-48cb-a265-ff601a75e872', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a9a73546-f652-4f3b-b4ba-1d4763fd0752', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bda3dbcd-9a54-444a-953b-ec470cf7b2fd', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a9a73546-f652-4f3b-b4ba-1d4763fd0752', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('434b2645-16cf-4ad9-b93e-2179a656d41c', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a9a73546-f652-4f3b-b4ba-1d4763fd0752', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab6bd774-2f78-40f0-a5b9-ac929debb2ce', '2026-11-24 23:57:17.492963+00', '2026-11-24 23:57:17.492963+00', 'a9a73546-f652-4f3b-b4ba-1d4763fd0752', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
